  const avg = team.skaters.reduce((a,p)=>a+p.rating,0)/team.skaters.length;
  const top3 = [...team.skaters].sort((a,b)=>b.rating-a.rating).slice(0,3);
  const topAvg = top3.reduce((a,p)=>a+p.rating,0)/3;
  const avgPts = team.skaters.reduce((a,p)=>a+(p.pts||0),0)/team.skaters.length;
