    const fs = rec.sim.factors.display.filter(f => f.hm !== 1 || f.am !== 1);
    let pick = [];
    if (pk && (pk.market === "ML" || pk.market === "SPR")) pick = fs.filter(f => f.side === pk.side);
    else if (pk && pk.market === "TOT") pick = fs.filter(f => { const a = (f.hm + f.am) / 2; return pk.side === "over" ? a > 1.004 : a < 0.996; });
    pick = pick.sort((x, y) => Math.abs(y.hm - y.am) + Math.abs(y.hm + y.am - 2) - Math.abs(x.hm - x.am) - Math.abs(x.hm + x.am - 2)).slice(0, 2);
