    const s = r.sim, px = priceGame(s.plan, sport, scale);
    r.proj = { home: (px.meanT + px.meanM) / 2, away: (px.meanT - px.meanM) / 2, margin: px.meanM, total: px.meanT, raw: { home: s.avgHome, away: s.avgAway } };
    const ratio = r.mkt.total > 0 ? r.unscaledTotal / r.mkt.total : null;
    const totalsOk = ratios.length >= 3 || ratio == null || Math.abs(ratio - 1) <= 0.2;
    r.totalSkipped = !totalsOk && r.mkt.total != null; r.skippedTotal = r.unscaledTotal;
    r.bets = candidates(r, px, sport, totalsOk);
    const f = DQ_FACTOR[Math.max(0, Math.min(6, r.dq))];
    r.bets.forEach(b => { b.score = b.kelly * 100 * f; });
    const pos = r.bets.filter(b => b.ev > 0).sort((a, b) => b.score - a.score || b.ev - a.ev);
    if (!r.bets.length) { r.status = "model"; r.pick = null; r.score = 0; r.conv = Math.abs(Math.max(r.pricing.pH, r.pricing.pA) - 0.5); }
    else if (pos.length) { r.status = "bet"; r.pick = pos[0]; r.score = pos[0].score; }
    else { r.status = "pass"; r.pick = [...r.bets].sort((a, b) => b.ev - a.ev)[0]; r.score = 0; }
    r.grade = r.status === "bet" ? gradeOf(r.pick, r.dq) : r.status === "pass" ? "PASS" : "LEAN*";
