// ─── KALSHI on the slip: each person's own key, kept on their device; every order confirmed before it's sent ─────
async function kalshiCall(rec, method, sub, body) {
  const env = rec?.env || "live", headers = rec?.key ? await signHeaders(rec, method, `${API_ROOT}/${sub}`) : {};
  let r;
  try { r = await fetch(`${API}/kalshi/${env}/${sub}`, { method, credentials: "same-origin", headers: { ...headers, "content-type": "application/json" }, body: body ? JSON.stringify(body) : undefined }); }
  catch (_) { throw new Error("Couldn't reach Kalshi. Check your connection and try again."); }
  const j = await r.json().catch(() => ({}));
  if (!r.ok) {
    const m = j?.error?.message || j?.error?.code || j?.message || j?.error || `Kalshi said no (${r.status})`;
    throw new Error(r.status === 401 ? "Kalshi didn't accept the key. Check the Key ID and private key in the KALSHI tab." : /insufficient/i.test(String(m)) ? `Kalshi says there isn't enough cash for this order where this market trades (Kalshi: "${String(m).slice(0, 160)}").` : String(m));
  }
  return j;
}
// What Kalshi actually filled for one order (GET portfolio/fills): the record a slip keeps is this, never a quote's
// numbers. Fills land a moment after an order executes, so it's read a few times; null if Kalshi never lists them.
async function kalshiFilled(kal, orderId, side = "yes", tries = 6) {
  if (!orderId) return null;
  for (let i = 0; i < tries; i++) {
    const j = await kalshiCall(kal, "GET", `portfolio/fills?order_id=${encodeURIComponent(orderId)}&limit=100`).catch(() => null);
    const t = fillTotals((j?.fills || []).filter(f => !f.order_id || f.order_id === orderId), side);
    if (t) return t;
    await new Promise(r => setTimeout(r, 500));
  }
  return null;
}
// ---- SYNC: every open position on this person's Kalshi (bought here or in the Kalshi app) becomes a ticket ----
// Runs on this device with their own key: reads the positions, looks up each market (and a combo's legs) on Kalshi's
// public data, and hands the site what it needs. A synced ticket that's no longer open was either settled (it grades
// itself from Kalshi's result) or sold in the app (settled here as cashed out at what Kalshi says it made).
let _syncing = null;
async function syncKalshi(kal) {
  if (!kal) return null;
  if (_syncing) return _syncing;
  _syncing = (async () => {
    const positions = [];
    let cursor = "";
    for (let i = 0; i < 5; i++) {
      const j = await kalshiCall(kal, "GET", `portfolio/positions?count_filter=position&limit=200${cursor ? `&cursor=${encodeURIComponent(cursor)}` : ""}`);
      positions.push(...(j.market_positions || []));
      cursor = j.cursor || "";
      if (!cursor) break;
    }
    const open = positions.filter(p => parseFloat(p.position_fp ?? p.position) !== 0);
    const mkts = {}, pub = { env: kal.env };
    const getM = t => (t in mkts ? null : kalshiCall(pub, "GET", `markets/${encodeURIComponent(t)}`).then(j => { mkts[t] = j.market || {}; }).catch(() => { mkts[t] = {}; }));
    for (let i = 0; i < open.length; i += 6) await Promise.all(open.slice(i, i + 6).map(p => getM(p.ticker)));
    const legT = [...new Set(open.flatMap(p => (mkts[p.ticker]?.mve_selected_legs || []).map(l => l.market_ticker)))];
    for (let i = 0; i < legT.length; i += 6) await Promise.all(legT.slice(i, i + 6).map(getM));
    const r = await api("POST", "slips/sync", { env: kal.env, positions: syncPayload(open, mkts) });
    let cashed = 0;
    for (const g of r.gone || []) {
      const m = await kalshiCall(pub, "GET", `markets/${encodeURIComponent(g.ticker)}`).then(j => j.market).catch(() => null);
      if (!m || m.result || /settled|finalized|determined|closed/.test(String(m.status || ""))) continue;      // settled: grading takes it
      const p = (await kalshiCall(kal, "GET", `portfolio/positions?ticker=${encodeURIComponent(g.ticker)}`).catch(() => ({}))).market_positions?.find(x => x.ticker === g.ticker);
      if (!p || parseFloat(p.position_fp ?? p.position) !== 0) continue;
      const made = (parseFloat(p.realized_pnl_dollars) || 0) - (parseFloat(p.fees_paid_dollars) || 0);
      await api("POST", `slips/${g.id}/cashout`, { proceeds: Math.max(0, Math.round((g.stake + made) * 100) / 100), sale: { how: "order" } }).then(() => { cashed++; }).catch(() => {});
    }
    return { added: r.added || 0, updated: r.updated || 0, cashed };
  })().finally(() => { setTimeout(() => { _syncing = null; }, 0); });
  return _syncing;
}

// the cash a buy needs, on the shard its market trades on (see planFunding in src/kalshi.js)
async function kalshiFundingPlan(kal, ticker, need) {
  const [mj, bal] = await Promise.all([kalshiCall({ env: kal.env }, "GET", `markets/${encodeURIComponent(ticker)}`).catch(() => null), kalshiCall(kal, "GET", "portfolio/balance")]);
  const ix = mj?.market?.exchange_index, shard = Number.isInteger(ix) ? ix : null;
  return planFunding(bal, shard, need);
}
// move the cash, then wait until Kalshi shows it on the market's shard (transfers settle asynchronously)
async function kalshiMoveFunds(kal, plan) {
  for (const m of plan.moves) await kalshiCall(kal, "POST", "portfolio/intra_exchange_instance_transfer", transferBody(m, crypto.randomUUID()));
  const t0 = Date.now();
  while (Date.now() - t0 < 15000) {
    await new Promise(r => setTimeout(r, 1200));                 // the balance endpoint allows about one call a second
    const b = await kalshiCall(kal, "GET", "portfolio/balance").catch(() => null);
    const v = parseFloat((b?.balance_breakdown || []).find(x => Number(x.exchange_index) === plan.shard)?.balance || "0");
    if (v >= plan.need - 1e-9) return true;
  }
  return false;
}
const shardName = ix => (ix === 3 ? "sports (tennis, baseball, basketball)" : ix === 1 ? "combos" : ix === 2 ? "crypto and commodities" : ix === 0 ? "default" : `#${ix}`);
// Kalshi's markets for the series a slip needs, refreshed every minute
const _kx = {};
async function kalshiEvents(env, series) {
  const k = `${env}|${series}`;
  if (_kx[k] && Date.now() - _kx[k].t < 60000) return _kx[k].p;
  const p = kalshiCall({ env }, "GET", `events?series_ticker=${series}&status=open&with_nested_markets=true&limit=200`).then(j => j.events || []).catch(() => []);
  _kx[k] = { t: Date.now(), p };
  return p;
}
const kalshiMoney = d => cash(d);

