// What each line maps to on Kalshi (or why it can't), from Kalshi's current markets
function useKalshiMap(kal, on, legs) {
  const [ev, setEv] = useState({}), [mk, setMk] = useState({});
  // a market picked straight from Kalshi's index: its own live quote, every 10 seconds
  const tickers = [...new Set(legs.filter(l => l && l.kalshi).map(l => l.ticker))], tkey = tickers.join(",");
  useEffect(() => {
    if (!kal || !on || !tickers.length) return;
    let alive = true;
    const pull = () => Promise.all(tickers.map(t => kalshiCall({ env: kal.env }, "GET", `markets/${encodeURIComponent(t)}`).then(j => [t, j.market || null]).catch(() => [t, null]))).then(r => alive && setMk(o => ({ ...o, ...Object.fromEntries(r) })));
    pull(); const iv = setInterval(pull, 10000);
    return () => { alive = false; clearInterval(iv); };
  }, [kal, on, tkey]);
  const need = [...new Set(legs.filter(l => l && !l.kalshi).flatMap(l => [seriesFor(l.sport, l.league, "ml"), l.market === "spread" || l.market === "total" ? seriesFor(l.sport, l.league, l.market) : null]).filter(Boolean))];
  const key = need.join(","), anyLive = legs.some(l => l && !l.kalshi && l.state === "in");   // a game in progress: live prices every 10 seconds
  useEffect(() => {
    if (!kal || !on || !need.length) return;
    let alive = true;
    Promise.all(need.map(s => kalshiEvents(kal.env, s).then(e => [s, e]))).then(r => alive && setEv(o => ({ ...o, ...Object.fromEntries(r) })));
    const t = setInterval(() => { need.forEach(s => delete _kx[`${kal.env}|${s}`]); Promise.all(need.map(s => kalshiEvents(kal.env, s).then(e => [s, e]))).then(r => alive && setEv(o => ({ ...o, ...Object.fromEntries(r) }))); }, anyLive ? 10000 : 60000);
    return () => { alive = false; clearInterval(t); };
  }, [kal, on, key, anyLive]);
  return legs.map(l => (!l ? null : l.kalshi ? (l.ticker in mk ? quoteMarket(mk[l.ticker], l) : { loading: true }) : need.every(s => s in ev) || [seriesFor(l.sport, l.league, "ml")].every(s => s in ev) ? mapLeg(l, ev) : { loading: true }));
}
function KalshiLine({ k, onLine }) {
  if (!k) return null;
  const box = c => ({ marginTop: 4, padding: "6px 10px", borderLeft: `2px solid ${c}`, background: `${c}10`, fontSize: 11, lineHeight: 1.5 });
  if (k.loading) return <div style={box(T.dim)}><span style={{ color: T.dim }}>Checking Kalshi…</span></div>;
  if (!k.ok) return <div style={box(NEON.gold)}>
    <span style={{ color: NEON.gold }}>Kalshi: {k.why}</span>
    {k.options?.length > 0 && <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 6 }}>
      <span style={{ color: T.faint }}>use Kalshi's:</span>
      {k.options.map(o => <button key={o.line} onClick={() => onLine(o.line)} style={{ padding: "3px 8px", border: `1px solid ${NEON.gold}66`, background: "none", color: T.ink, fontFamily: F.m, fontSize: 11, cursor: "pointer", whiteSpace: "nowrap" }}>{o.text}</button>)}
    </div>}
  </div>;
  return <div style={box(NEON.teal)}>
    <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 8 }}>
      <span style={{ color: T.ink, overflowWrap: "anywhere" }}>Kalshi: {k.label} · buy {k.side.toUpperCase()}</span>
      <span style={{ fontFamily: F.d, color: "#fff", whiteSpace: "nowrap" }}>{cents(k.price)} ({fmtAm(k.am)})</span>
    </div>
  </div>;
}

// The review step before anything is bought: exactly what goes to Kalshi, then the result
function KalshiReview({ kal, plan, stake, onDone, onCancel }) {
  const [st, setSt] = useState({ step: "review" }), cancelled = useRef(false);
  useEffect(() => () => { cancelled.current = true; }, []);
  const straight = plan.length === 1, k = plan[0].k, size = straight ? sizeOrder(stake, k.price) : null;
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  // the cash this buy needs, checked before anything is sent: where it sits and what has to move to the market's shard
  const need = straight ? Math.round(((size?.cost || 0) + (size?.fee || 0)) * 100) / 100 : stake;
  const [fund, setFund] = useState(null);
  useEffect(() => {
    if (!straight || !size) return;
    let on = true;
    setFund(null);
    kalshiFundingPlan(kal, k.ticker, need).then(p => on && setFund(p)).catch(e => on && setFund({ err: e.message }));
    return () => { on = false; };
  }, [k?.ticker, need, kal?.env]);
  const short = p => `Not enough cash in your Kalshi account: ${kalshiMoney(p.total)} available, this needs ${kalshiMoney(p.need)} with the fee. Nothing was bought.`;
  // fund the market's shard if needed (what the Kalshi app does on its own), then the order can go
  const fundFor = async (ticker, amount) => {
    const p = await kalshiFundingPlan(kal, ticker, amount);
    if (!p.covered) throw new Error(short(p));
    if (p.moves.length) {
      setSt({ step: "sending", what: `Moving ${kalshiMoney(p.moves.reduce((a, m) => a + m.amount, 0))} to Kalshi's ${shardName(p.shard)} shard…` });
      if (!(await kalshiMoveFunds(kal, p))) throw new Error("The cash move inside your Kalshi account hasn't landed yet. Nothing was bought. Try again in a few seconds.");
    }
  };
  const buyStraight = async () => {
    setSt({ step: "sending" });
    try {
      await fundFor(k.ticker, need);
      setSt({ step: "sending" });
      const yesPrice = k.side === "yes" ? k.price : 1 - k.price;
      const o = await kalshiCall(kal, "POST", "portfolio/events/orders", { ticker: k.ticker, side: k.side === "yes" ? "bid" : "ask", count: size.count.toFixed(2), price: yesPrice.toFixed(2), time_in_force: "fill_or_kill", self_trade_prevention_type: "taker_at_cross", client_order_id: crypto.randomUUID() });
      const filled = parseFloat(o.fill_count || "0");
      if (!(filled > 0)) { setSt({ step: "failed", msg: "The price moved before it filled, so nothing was bought. Review the new price and try again." }); return; }
      const avgYes = parseFloat(o.average_fill_price || yesPrice), paid0 = k.side === "yes" ? avgYes : 1 - avgYes;
      // the slip keeps what Kalshi actually filled and charged (fees included), read back from the fills
      const real = await kalshiFilled(kal, o.order_id, k.side), n = real?.count || filled, paid = real?.price || paid0;
      const cost = real ? real.total : Math.round((n * paid + feeEstimate(n, paid)) * 100) / 100;
      onDone({ cost, legOdds: [priceToAm(paid)], kalshi: { env: kal.env, dec: n / cost, orders: [{ ticker: k.ticker, side: k.side, count: n, price: paid, order_id: o.order_id, filled: n }] }, summary: `Bought ${n} ${k.side.toUpperCase()} at ${cents(paid)} on Kalshi for ${kalshiMoney(cost)} with the fee.` });
    } catch (e) { setSt({ step: "failed", msg: e.message }); }
  };
  // ---- combos: Kalshi prices them through market makers (an RFQ). The ask goes out as soon as this review opens and stays
  // open, re-reading the makers' quotes every second, so a live price is already there when you tap. One tap buys it.
  const live = useRef(null), buying = useRef(false), rfqRef = useRef(null);
  const [q, setQ] = useState(null), [waited, setWaited] = useState(0), [round, setRound] = useState(0), stepRef = useRef("review");
  stepRef.current = st.step;
  useEffect(() => {
    if (straight) return;
    let alive = true, fails = 0;
    const t0 = Date.now();
    (async () => {
      try {
        const colls = await kalshiCall({ env: kal.env }, "GET", "multivariate_event_collections?status=open&limit=200").then(j => j.multivariate_contracts || j.multivariate_event_collections || []);
        const c = comboCollection(colls, plan.map(p => p.k));
        if (!c) { alive && setSt({ step: "failed", msg: "Kalshi doesn't offer this combination as a combo (some legs can't be combined). Nothing was bought." }); return; }
        const made = await kalshiCall(kal, "POST", `multivariate_event_collections/${c.collection_ticker}`, { selected_markets: plan.map(p => ({ event_ticker: p.k.event_ticker, market_ticker: p.k.ticker, side: p.k.side })) });
        let n = 0;
        while (alive && !cancelled.current && stepRef.current !== "failed") {
          if (!buying.current) {
            try {
              if (!rfqRef.current) rfqRef.current = (await kalshiCall(kal, "POST", "communications/rfqs", { market_ticker: made.market_ticker, target_cost_dollars: stake.toFixed(2), rest_remainder: false, replace_existing: true })).id;
              const best = bestComboQuote((await kalshiCall(kal, "GET", quotesPath(rfqRef.current))).quotes);
              live.current = best ? { best, rfq: rfqRef.current, market: made.market_ticker, coll: c.collection_ticker } : null;
              if (alive) { setQ(live.current); setWaited(Math.round((Date.now() - t0) / 1000)); }
              // every few seconds: is the ask still open on Kalshi? if it expired, ask again
              if (++n % 8 === 0) { const r = await kalshiCall(kal, "GET", `communications/rfqs/${rfqRef.current}`).catch(() => null); if (r && (r.rfq?.status || r.status) && (r.rfq?.status || r.status) !== "open") rfqRef.current = null; }
              fails = 0;
            } catch (e) {
              // a real error from Kalshi is shown, never quietly read as "no quotes"
              if (++fails >= 3) { if (alive) setSt({ step: "failed", msg: `Kalshi: ${e.message} Nothing was bought.` }); return; }
              rfqRef.current = null;
            }
          }
          await sleep(1000);
        }
      } catch (e) { if (alive) setSt({ step: "failed", msg: e.message }); }
    })();
    return () => { alive = false; if (rfqRef.current && !buying.current) kalshiCall(kal, "DELETE", `communications/rfqs/${rfqRef.current}`).catch(() => {}); };
  }, [round]);
  // one tap: buy the live quote; if a maker backs out in the 3-second window, take the next one at that price or better
  const buyCombo = async () => {
    const want = live.current;
    if (!want || comboCost(want.best, stake)?.over) return;
    const cap = want.best.price, tried = new Set();
    buying.current = true; setSt({ step: "accepting" });
    try {
      await fundFor(want.market, stake);                                                          // combos trade on their own shard
      setSt({ step: "accepting" });
      const t0 = Date.now();
      let pick = want.best, rfq = want.rfq;
      while (Date.now() - t0 < 20000) {
        if (!pick) {
          await sleep(500);
          rfq = rfqRef.current || rfq;
          pick = bestComboQuote((await kalshiCall(kal, "GET", quotesPath(rfq)).catch(() => ({ quotes: [] }))).quotes, { maxPrice: cap, skip: tried });
          if (pick && comboCost(pick, stake)?.over) { tried.add(pick.quote.id); pick = null; }       // never more than the slip says
          continue;
        }
        tried.add(pick.quote.id);
        const ok = await kalshiCall(kal, "PUT", `communications/rfqs/${rfq}/quotes/${pick.quote.id}/accept`, { accepted_side: "no" }).then(() => true).catch(() => false);   // the maker's NO side = buying YES
        const s0 = Date.now();
        while (ok && Date.now() - s0 < 6000) {                                                    // combos: 3s for the maker to confirm, 1s to execute
          await sleep(600);
          const mine = ((await kalshiCall(kal, "GET", quotesPath(rfq)).catch(() => ({ quotes: [] }))).quotes || []).find(x => x.id === pick.quote.id);
          if (mine?.status === "executed") {
            // the slip keeps what Kalshi actually filled and charged (fees included): the fills for this buy's own order.
            // If Kalshi doesn't list them yet, the size of the side that was bought (the maker's NO side), never the other.
            const qPrice = 1 - parseFloat(mine.no_bid_dollars || pick.quote.no_bid_dollars);
            const real = await kalshiFilled(kal, mine.rfq_creator_order_id, "yes");
            const nC = real?.count || buyYesContracts(mine) || pick.contracts || comboCost({ price: qPrice }, stake)?.contracts || 0, price = real?.price || qPrice;
            const cost = real ? real.total : Math.round((nC * price + feeEstimate(nC, price)) * 100) / 100;
            rfqRef.current = null;
            onDone({ cost, legOdds: plan.map(p => p.k.am), kalshi: { env: kal.env, dec: nC / cost, orders: [], combo: { market_ticker: want.market, collection: want.coll, rfq_id: rfq, quote_id: mine.id, price, contracts: nC } }, summary: `Combo bought on Kalshi: ${nC} YES at ${cents(price)} for ${kalshiMoney(cost)} with the fee. Pays ${kalshiMoney(nC)} if every leg wins.` });
            return;
          }
          if (!mine || mine.status === "cancelled") break;
        }
        pick = null;
      }
      setSt({ step: "review", note: `No maker would fill it at ${cents(cap)} or better just now, so nothing was bought. The live price is below.` });
    } catch (e) { setSt({ step: "failed", msg: e.message }); }
    finally { buying.current = false; }
  };
  const cc = q ? comboCost(q.best, stake) : null;
  const row = (a, b, c) => <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 10, padding: "5px 0", borderTop: `1px solid ${T.line}`, fontSize: 12 }}><span style={{ color: T.dim }}>{a}</span><span style={{ fontFamily: F.d, color: c || T.ink, textAlign: "right" }}>{b}</span></div>;
  const big = (on, txt, fn, c = T.chrome) => <button onClick={fn} disabled={!on} style={{ width: "100%", marginTop: 10, padding: 13, border: `1px solid ${on ? c : T.line}`, background: on ? `${c}33` : "none", color: on ? "#fff" : T.faint, fontFamily: F.d, fontSize: 12, letterSpacing: 2, cursor: on ? "pointer" : "not-allowed" }}>{txt}</button>;
  return <div style={{ marginTop: 12, border: `1px solid ${NEON.teal}88`, background: "rgba(23,242,208,.05)", padding: 12 }}>
    <div style={{ fontFamily: F.d, fontSize: 11, letterSpacing: 2, color: NEON.teal }}>REVIEW · KALSHI {kal.env === "demo" ? "DEMO" : "LIVE"}</div>
    <div style={{ marginTop: 8 }}>{plan.map((p, i) => <div key={i} style={{ fontSize: 12, color: T.ink, padding: "3px 0", overflowWrap: "anywhere" }}>{plan.length > 1 ? `${i + 1}. ` : ""}{p.k.label} · {p.k.side.toUpperCase()} {cents(p.k.price)}</div>)}</div>
    {straight && size && <div style={{ marginTop: 8 }}>
      {row("Contracts", size.count.toFixed(2))}{row("Price", `${cents(k.price)} (${fmtAm(k.am)})`)}{row("Cost", kalshiMoney(size.cost))}{row("Kalshi fee (est.)", kalshiMoney(size.fee))}{row("Pays if it wins", kalshiMoney(size.payout), NEON.green)}
      {row("Your Kalshi cash", !fund ? "checking…" : fund.err ? "couldn't check" : kalshiMoney(fund.total), fund && !fund.err && !fund.covered ? NEON.red : undefined)}
      {fund && !fund.err && fund.covered && fund.moves.length > 0 && <div style={{ fontSize: 11, color: T.dim, lineHeight: 1.6, marginTop: 6 }}>This market trades on Kalshi's {shardName(fund.shard)} shard, which holds {kalshiMoney(fund.here)} of your cash. The slip moves {kalshiMoney(fund.moves.reduce((a, m) => a + m.amount, 0))} there first, inside your Kalshi account (the Kalshi app does this on its own), then buys.</div>}
      {fund && !fund.err && !fund.covered && <div style={{ marginTop: 8, padding: "10px 12px", border: "1px solid #FF335566", background: "rgba(255,51,85,.08)", fontSize: 12, color: "#FF8095", lineHeight: 1.5 }}>Not enough cash in your Kalshi account: {kalshiMoney(fund.total)} available, this needs {kalshiMoney(fund.need)} with the fee.</div>}
    </div>}
    {!straight && (st.step === "review" || st.step === "accepting") && <div style={{ marginTop: 8 }}>
      {row("Combo price", q ? `${cents(q.best.price)} (${fmtAm(q.best.am)})` : "asking Kalshi…", q ? undefined : T.dim)}{row("Contracts", cc ? `${cc.est ? "about " : ""}${cc.contracts.toFixed(2)}` : "—")}{row("Cost", cc ? kalshiMoney(cc.cost) : "—")}{row("Kalshi fee (est.)", cc ? kalshiMoney(cc.fee) : "—")}{row("You pay", cc ? kalshiMoney(cc.total) : "—", cc?.over ? NEON.red : "#fff")}{row("Pays if every leg wins", cc ? kalshiMoney(cc.payout) : "—", NEON.green)}
      {cc?.over && <div style={{ marginTop: 8, padding: "10px 12px", border: "1px solid #FF335566", background: "rgba(255,51,85,.08)", fontSize: 12, color: "#FF8095", lineHeight: 1.5 }}>Kalshi's quote would cost {kalshiMoney(cc.total)}, more than the {kalshiMoney(stake)} on this slip, so it can't be bought. Still asking for one that fits.</div>}
      {cc?.short && <div style={{ fontSize: 12, color: NEON.gold, marginTop: 6, lineHeight: 1.5 }}>Kalshi's quote covers {kalshiMoney(cc.total)} of the {kalshiMoney(stake)} on this slip. Confirming buys {kalshiMoney(cc.total)}.</div>}
      <div style={{ fontSize: 11, color: T.faint, marginTop: 6, lineHeight: 1.5 }}>{q ? `Live from Kalshi's market makers, refreshed every second. The slip records what Kalshi actually fills, read back from your account.` : waited >= 15 ? "No Kalshi market maker has priced this combo yet. Still asking every second; nothing is bought until you confirm." : "Kalshi prices combos through market makers. Getting the price…"}</div>
      {st.note && <div style={{ fontSize: 12, color: NEON.gold, marginTop: 6, lineHeight: 1.5 }}>{st.note}</div>}
    </div>}
    {st.step === "failed" && <div style={{ marginTop: 10, padding: "10px 12px", border: "1px solid #FF335566", background: "rgba(255,51,85,.08)", fontSize: 12, color: "#FF8095", lineHeight: 1.5 }}>{st.msg}</div>}
    {st.step === "sending" && st.what && <div style={{ fontSize: 12, color: T.dim, marginTop: 8 }}>{st.what}</div>}
    {straight && (st.step === "review" || st.step === "sending") && big(st.step === "review" && !(fund && !fund.err && !fund.covered), st.step === "sending" ? "SENDING TO KALSHI…" : `CONFIRM: BUY ON KALSHI FOR ${kalshiMoney(need)}`, buyStraight, NEON.teal)}
    {!straight && (st.step === "review" || st.step === "accepting") && big(st.step === "review" && !!cc && !cc.over, st.step === "accepting" ? "BUYING ON KALSHI…" : cc ? `CONFIRM: BUY THE COMBO FOR ${kalshiMoney(cc.total)}` : "GETTING KALSHI'S PRICE…", buyCombo, NEON.teal)}
    {st.step === "failed" && big(true, "TRY AGAIN", () => { rfqRef.current = null; setQ(null); setSt({ step: "review" }); setRound(r => r + 1); })}
    <button onClick={onCancel} disabled={st.step === "sending" || st.step === "accepting"} style={{ width: "100%", marginTop: 8, padding: 10, border: `1px solid ${T.line}`, background: "none", color: T.dim, fontFamily: F.d, fontSize: 11, letterSpacing: 2, cursor: "pointer" }}>CANCEL</button>
  </div>;
}

// under each line: which game it matched (or why it didn't), and other games it could mean
function PickMatch({ x, onChoose, fmt = "am", toK = false }) {
  if (x.empty) return null;
  const box = c => ({ marginTop: 6, padding: "7px 10px", borderLeft: `2px solid ${c}`, background: `${c}12`, fontSize: 11, lineHeight: 1.5, color: T.ink });
  if (x.res.status === "loading") return <div style={box(T.dim)}><span style={{ color: T.dim }}>Loading today's games…</span></div>;
  if (!x.leg) {
    const opts = [...(x.res.leg ? [x.res.leg] : []), ...(x.res.others || [])];
    if (!opts.length) return <div style={box(NEON.red)}><span style={{ color: "#FF8095" }}>{x.res.status === "empty" ? "Type a team or player and a bet." : "Nothing matches that today, tomorrow or on Kalshi. Try the team's or player's name, city or abbreviation."}</span></div>;
    return <div style={box(T.chrome)}>
      <div style={{ color: T.ink, marginBottom: 6 }}>Tap your pick to put it on this line:</div>
      <div style={{ display: "grid", gap: 6 }}>
        {opts.map(o => { const kx = !!o.kalshi, started = !kx && o.state !== "pre";
          return <button key={`${o.sport}${o.eventId}${o.side}${o.market}`} onClick={() => onChoose(o)} style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 8, width: "100%", padding: "8px 10px", border: `1px solid ${T.line}`, background: "rgba(14,4,26,.6)", color: T.ink, fontFamily: F.m, fontSize: 11, textAlign: "left", cursor: "pointer", lineHeight: 1.45 }}>
            <span style={{ minWidth: 0, overflowWrap: "anywhere" }}><span style={{ color: "#fff", fontWeight: 700 }}>{legLabel(o)}</span><br/><span style={{ color: T.dim }}>{gameTxt(o)} · {kx ? "on Kalshi" : o.state === "in" ? "LIVE" : o.state === "post" ? "over" : whenTxt(o.date)}</span></span>
            <span style={{ color: started ? NEON.gold : T.dim, whiteSpace: "nowrap" }}>{kx ? `Kalshi · ${SPORT_CFG[o.sport]?.label || o.sport}` : SPORT_CFG[o.sport]?.label || o.sport}</span>
          </button>; })}
      </div>
    </div>;
  }
  const l = x.leg, kx = !!l.kalshi, live = !kx && l.state === "in", over = !kx && l.state === "post", bettable = kx ? toK : l.state === "pre" || (live && toK);
  // the other matches for what was typed: the typed match itself when another was chosen, never the one now in the line
  const same = (a, b) => a.sport === b.sport && String(a.eventId) === String(b.eventId) && a.side === b.side && a.market === b.market;
  const others = [...(x.res.leg && !same(x.res.leg, l) ? [x.res.leg] : []), ...(x.res.others || []).filter(o => !same(o, l) && !(x.res.leg && same(o, x.res.leg)))];
  const c = bettable ? NEON.green : live ? NEON.gold : NEON.red;
  return <div style={box(c)}>
    <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 8 }}>
      <span style={{ color: bettable ? NEON.green : "#fff", fontWeight: bettable ? 700 : 400, overflowWrap: "anywhere" }}>{bettable ? "✓ " : live ? "● " : "✗ "}{legLabel(l)}</span>
      <span style={{ color: T.dim, whiteSpace: "nowrap" }}>{kx ? `Kalshi · ${SPORT_CFG[l.sport]?.label || l.sport}` : SPORT_CFG[l.sport]?.label || l.sport}</span>
    </div>
    <div style={{ color: T.dim, overflowWrap: "anywhere" }}>{gameTxt(l)} · {kx ? (toK ? <span style={{ color: NEON.teal }}>on Kalshi, live or upcoming{l.date ? ` · closes ${whenTxt(l.date)}` : ""}</span> : "a Kalshi market: turn on Send to Kalshi to bet it") : over ? "this game is over" : live ? (toK ? <span style={{ color: NEON.red }}>● LIVE: bet it now at Kalshi's live price</span> : "live: turn on Send to Kalshi to bet it live") : whenTxt(l.date)}</div>
    {x.l.odds && x.odds == null && <div style={{ color: "#FF8095" }}>{fmt === "pct" ? "Use a percentage from 1 to 99, like 54." : "Odds look like -110 or +150."}</div>}
    {!x.l.odds && !kx && <div style={{ color: T.dim }}>Add the odds on the right.</div>}
    {!x.l.choice && others.length > 0 && <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 6 }}>
      <span style={{ color: T.faint }}>or:</span>
      {others.map(o => <button key={`${o.sport}${o.eventId}${o.side}`} onClick={() => onChoose(o)} style={{ ...oneLine, maxWidth: "100%", padding: "3px 8px", border: `1px solid ${T.line}`, background: "none", color: T.dim, fontFamily: F.m, fontSize: 11, cursor: "pointer" }}>{legLabel(o)} · {o.kalshi ? `Kalshi · ${o.title}` : SPORT_CFG[o.sport]?.label}</button>)}
    </div>}
  </div>;
}

// ---------- a bettor's page: numbers, then every slip ----------
function Bettor({ path, mine = false, onChange, onBackBoard, backLabel = "LEADERBOARD", username, onRenamed, kal = null, onCashed }) {
  const [d, setD] = useState(null), [err, setErr] = useState(null), [rename, setRename] = useState(false);
  const load = () => api("GET", path).then(setD).catch(e => setErr(e.message));
  const { gameOf, isLiveNow, track } = useLegTrack(d?.slips, mine && !!d?.slips?.some(x => x.status === "pending"));
  useEffect(() => { load(); }, [path]);
  if (err) return <Panel color={NEON.red}><div style={{ fontSize: 13, color: "#FF8095" }}>{err}</div></Panel>;
  if (!d) return <Panel><div style={{ fontSize: 12, color: T.dim }}>Grading and loading…</div></Panel>;
  const s = d.stats;
  return <>
    {onBackBoard && <button onClick={onBackBoard} style={{ ...btnStyle(), marginTop: 14 }}>◂ {backLabel}</button>}
    {rename && <UsernamePanel current={username} onDone={u => { setRename(false); onRenamed && onRenamed(u); }}/>}
    <Panel title={mine ? "MY NUMBERS" : d.username.toUpperCase()} right={mine ? <button onClick={() => setRename(!rename)} style={{ background: "none", border: "none", color: T.dim, fontFamily: F.m, fontSize: 11, cursor: "pointer", padding: 0, textDecoration: "underline" }}>{d.username} · change</button> : `${s.pending} pending`}>
      <StatGrid s={s}/>
      {Object.keys(s.bySport).length > 0 && <div style={{ marginTop: 12, display: "flex", flexWrap: "wrap", gap: 6 }}>
        {Object.entries(s.bySport).map(([sp, b]) => <span key={sp} style={{ padding: "4px 8px", border: `1px solid ${T.line}`, fontSize: 11, color: T.dim, whiteSpace: "nowrap" }}>{SPORT_CFG[sp]?.label || sp} <b style={{ color: T.ink }}>{b.W}-{b.L}</b> <span style={{ color: b.net >= 0 ? NEON.green : NEON.red }}>{sCash(b.net)}</span></span>)}
      </div>}
    </Panel>
    <Panel title={mine ? "MY SLIPS" : "SLIPS"} right={`${d.slips.length} total`}>
      {!d.slips.length && <div style={{ fontSize: 12, color: T.dim }}>{mine ? "No slips yet. Add one on NEW SLIP." : "No slips yet."}</div>}
      {d.slips.map(sl => <SlipCard key={sl.id} sl={sl} canTakeBack={mine} track={mine && isLiveNow(sl) ? track : null} gameOfLeg={mine ? gameOf : null} foot={mine && sl.status === "pending" && sl.kalshi ? <CashOut sl={sl} kal={kal} onCashed={m => { onCashed && onCashed(m); load(); onChange && onChange(); }}/> : null} onTakeBack={async () => { try { await api("DELETE", `slips/${sl.id}`); load(); onChange && onChange(); } catch (e) { setErr(e.message); } }}/>)}
    </Panel>
  </>;
}
function StatGrid({ s }) {
  const cells = [["RECORD", `${s.W}-${s.L}${s.P ? `-${s.P}` : ""}`, T.ink], ["WIN %", pctTxt(s.pct), T.ink], ["NET", sCash(s.net), s.net > 0 ? NEON.green : s.net < 0 ? NEON.red : T.ink],
    ["WON", cash(s.won), NEON.green], ["STAKED", cash(s.staked), T.ink], ["ROI", s.roi == null ? "–" : `${s.roi > 0 ? "+" : ""}${(s.roi * 100).toFixed(1)}%`, T.ink],
    ["STREAK", s.streak || "–", s.streak?.[0] === "W" ? NEON.green : s.streak?.[0] === "L" ? NEON.red : T.ink], ["BEST WIN", s.best ? cash(s.best.profit) : "–", T.ink], ["PARLAYS", `${s.parlays.W}-${s.parlays.L}`, T.ink], ["PENDING", String(s.pending), T.chrome]];
  return <div className="bb-stats" style={{ display: "grid", gap: 8 }}>
    {cells.map(([k, v, c]) => <div key={k} style={{ minWidth: 0, border: `1px solid ${T.line}`, padding: "9px 10px", background: "rgba(9,2,17,.5)" }}>
      <div style={{ fontSize: 10, color: T.faint, letterSpacing: 1 }}>{k}</div>
      <div style={{ ...oneLine, fontFamily: F.d, fontSize: "clamp(13px,3.4vw,15px)", fontWeight: 700, color: c, marginTop: 3 }}>{v}</div>
    </div>)}
  </div>;
}
function SlipCard({ sl, canTakeBack, onTakeBack, top = null, liveRows = null, foot = null, track = null, gameOfLeg = null }) {
  const c = STATUS_C[sl.status], open = sl.status === "pending" && sl.legs.every(l => !l.res && Date.parse(l.date) > Date.now());
  const mark = r => (r === "W" ? ["✓", NEON.green] : r === "L" ? ["✗", NEON.red] : r === "P" ? ["P", T.dim] : ["•", T.faint]);
  const liveLeg = l => { const r = l.res ? null : gameOfLeg ? gameOfLeg(l) : liveRows ? liveRows.get(`${l.sport}|${l.eventId}`) : null; return r && r.state === "in" ? r : null; };
  const isLive = sl.status === "pending" && sl.legs.some(l => liveLeg(l) || l.res || Date.parse(l.date) <= Date.now());
  return <div style={{ marginTop: 10, border: `1px solid ${isLive ? NEON.red : c}66`, background: `${isLive ? NEON.red : c}0d`, padding: "10px 12px" }}>
    {top}
    <div style={{ display: "grid", gridTemplateColumns: "auto minmax(0,1fr) auto", gap: 10, alignItems: "baseline" }}>
      <span style={{ fontFamily: F.d, fontSize: 11, letterSpacing: 1.5, color: isLive ? NEON.red : c, whiteSpace: "nowrap" }}>{isLive ? <><span style={{ animation: "blink 1.6s infinite" }}>●</span> LIVE</> : sl.status === "cashed" ? "CASHED OUT" : sl.status.toUpperCase()}</span>
      <span style={{ minWidth: 0, overflowWrap: "anywhere", fontSize: 11, color: T.dim }}>{sl.legs.length > 1 ? `${sl.legs.length}-leg parlay` : "straight"} · {new Date(sl.created).toLocaleDateString("en-US", { timeZone: "America/New_York", month: "short", day: "numeric" })}{sl.kalshi ? <span style={{ color: NEON.teal }}> · KALSHI{sl.kalshi.env === "demo" ? " DEMO" : ""}{sl.kalshi.imported ? " APP" : ""}</span> : null}</span>
      <span style={{ fontFamily: F.d, fontSize: 13, color: "#fff", whiteSpace: "nowrap" }}>{oddsAs(sl.odds, oddsPref())}</span>
    </div>
    <div style={{ marginTop: 8 }}>
      {sl.legs.map((l, i) => { const [m, mc] = mark(l.res), pg = track ? track(l) : null, liveC = pg && pg.kind === "status" && pg.win != null ? (pg.win ? NEON.green : NEON.red) : "#FF8095"; return <div key={i} style={{ display: "grid", gridTemplateColumns: "14px minmax(0,1fr) auto", gap: 8, alignItems: "baseline", padding: "4px 0", borderTop: i ? `1px solid ${T.line}` : "none" }}>
        <span style={{ color: mc, fontWeight: 700 }}>{m}</span>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: 12, color: T.ink, overflowWrap: "anywhere" }}>{legLabel(l)}</div>
          {pg && <LegBar p={pg} res={l.res}/>}
          {(r => r ? <div style={{ fontSize: 10, color: liveC, overflowWrap: "anywhere", marginTop: 1 }}>LIVE · {r.sport === "Tennis" || r.sport === "MMA" ? `${r.away.name} ${r.away.score || ""} · ${r.home.name} ${r.home.score || ""}` : `${r.away.abbr || r.away.name} ${r.away.score}-${r.home.score} ${r.home.abbr || r.home.name}`}{r.detail ? ` · ${r.detail}` : ""}</div>
            : <div style={{ fontSize: 10, color: T.faint, overflowWrap: "anywhere", marginTop: 1 }}>{shortGame(l)}{l.final && l.sport !== "Tennis" && l.sport !== "MMA" ? ` · final ${l.final.a}-${l.final.h}` : l.res ? "" : ` · ${whenTxt(l.date)}`}</div>)(liveLeg(l))}
        </div>
        <span style={{ fontFamily: F.d, fontSize: 11, color: T.dim, whiteSpace: "nowrap" }}>{oddsAs(l.odds, oddsPref())}</span>
      </div>; })}
    </div>
    <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 10, alignItems: "center", marginTop: 8, paddingTop: 8, borderTop: `1px solid ${T.line}` }}>
      <span style={{ fontSize: 12, color: T.dim, lineHeight: 1.5 }}>Bet <b style={{ color: T.ink }}>{cash(sl.stake)}</b>{sl.status === "pending" ? <> · to win <b style={{ color: NEON.green }}>{cash(sl.stake * ((sl.kalshi?.dec > 1 ? sl.kalshi.dec : amToDec(sl.odds)) - 1))}</b></> : sl.status === "won" ? <> · won <b style={{ color: NEON.green }}>{cash(sl.profit)}</b></> : sl.status === "lost" ? <> · lost <b style={{ color: NEON.red }}>{cash(sl.stake)}</b></> : sl.status === "cashed" ? <> · cashed out <b style={{ color: NEON.gold }}>{cash(sl.stake + sl.profit)}</b> <span style={{ color: sl.profit > 0 ? NEON.green : sl.profit < 0 ? NEON.red : T.dim }}>({sCash(sl.profit)})</span></> : " · refunded"}</span>
      {canTakeBack && open && !sl.kalshi ? <button onClick={onTakeBack} style={{ background: "none", border: `1px solid ${T.line}`, color: T.dim, fontFamily: F.m, fontSize: 10, padding: "4px 8px", cursor: "pointer", whiteSpace: "nowrap" }}>take back</button> : <span/>}
    </div>
    {foot}
  </div>;
}

// someone else's Kalshi ticket on LIVE NOW: what it would cash out for right now (only its owner can cash it out).
// Straights and combos with buyers on the book: Kalshi's live bids for those contracts. Other combos: an estimate from each
// leg's current bid (no one can ask Kalshi's market makers on someone else's behalf).
function CashValue({ sl }) {
  const K = sl.kalshi, [v, setV] = useState(null);
  useEffect(() => {
    if (!K?.mkt || !(K.count > 0)) return;
    let alive = true, timer = null;
    const pull = async () => {
      if (typeof document !== "undefined" && document.hidden) { timer = setTimeout(pull, 5000); return; }
      let next = 4000;                                       // a combo estimate takes a few lookups: every 4 seconds
      try {
        const env = { env: K.env }, book = (await kalshiCall(env, "GET", `markets/${encodeURIComponent(K.mkt)}/orderbook`)).orderbook_fp, sv = sellValue(book, K.side, K.count);
        if (sv.ok) { alive && setV({ value: sv.net, how: "bids" }); next = 2000; }
        else if (K.combo) {
          const legs = (await kalshiCall(env, "GET", `markets/${encodeURIComponent(K.mkt)}`)).market?.mve_selected_legs || [];
          const mk = await Promise.all(legs.map(l => kalshiCall(env, "GET", `markets/${encodeURIComponent(l.market_ticker)}`).then(j => ({ side: l.side, market: j.market })).catch(() => ({ side: l.side, market: null }))));
          const p = comboEstimate(mk);
          alive && setV(p ? { value: Math.round((K.count * p - feeEstimate(K.count, p)) * 100) / 100, how: "est" } : { none: true });
        } else alive && setV({ none: true });
      } catch (_) { /* keep the last value */ }
      if (alive) timer = setTimeout(pull, next);
    };
    pull();
    return () => { alive = false; clearTimeout(timer); };
  }, [K?.mkt]);
  if (!K?.mkt) return null;
  const pl = v && v.value != null ? Math.round((v.value - sl.stake) * 100) / 100 : null;
  return <div style={{ marginTop: 8, paddingTop: 8, borderTop: `1px solid ${T.line}`, fontSize: 12, color: T.dim, lineHeight: 1.5 }}>
    <div>Cash out now {pl != null ? <><b style={{ color: "#fff" }}>{cash(v.value)}</b> <span style={{ color: pl > 0 ? NEON.green : pl < 0 ? NEON.red : T.dim }}>({sCash(pl)})</span></> : <span style={{ color: T.faint }}>{v?.none ? "no bids on Kalshi right now" : "…"}</span>}</div>
    <div style={{ fontSize: 10, color: T.faint, overflowWrap: "anywhere" }}>{v?.how === "est" ? "Estimate from each leg's live Kalshi price" : "Kalshi's live bids, after fees"} · only {sl.username} can cash it out</div>
  </div>;
}

// under a leg on a live ticket: an empty line that fills purple as the stat comes in, and turns green once it clears
function LegBar({ p, res }) {
  if (!p || p.kind === "status") return null;                 // moneylines: the LIVE score line under it is green / red
  const c = res === "L" ? NEON.red : res === "W" ? NEON.green : p.win === true ? NEON.green : p.win === false ? NEON.red : NEON.purple;
  const fmt = v => (Number.isInteger(v) ? String(v) : String(Math.round(v * 10) / 10));
  const sgn = v => (v > 0 ? `+${fmt(v)}` : v === 0 ? "PK" : fmt(v));
  const track = { height: 6, background: "rgba(241,230,255,.07)", border: `1px solid ${T.line}`, overflow: "hidden", position: "relative" };
  // a number riding above the bar: `at` is where along it (0-100), `anchor` which edge of the number sits there
  const tag = (txt, at, color, anchor = "mid", key) => <span key={key} style={{ position: "absolute", bottom: 0, left: `${at}%`, transform: anchor === "end" ? "translateX(-100%)" : anchor === "start" ? "none" : `translateX(-${at}%)`, fontFamily: F.d, fontSize: 10, fontWeight: 700, color, whiteSpace: "nowrap", lineHeight: 1, transition: "left .6s ease, transform .6s ease" }}>{txt}</span>;
  const above = kids => <div style={{ position: "relative", height: 13, marginTop: 4 }}>{kids}</div>;
  if (p.kind === "margin") {
    // the line in the middle; the fill runs green to the right by how much it's covering, red to the left by how much
    // it's short, and that many points (from covering) ride on the end of it
    // covering: the whole line goes green to the end (like a prop that's cleared); the team's lead rides on the fill's end
    const cover = p.m > 0, w = cover ? 50 : Math.min(50, (Math.abs(p.m) / p.scale) * 50), gap = Math.max(w, 10), end = cover ? 100 : p.m === 0 ? 60 : 50 - gap;
    return <div>
      {above([tag(sgn(p.line), 50, T.ink, "mid", "l"), tag(fmt(p.lead ?? Math.abs(p.m)), end, c, cover ? "end" : p.m === 0 ? "start" : (end < 12 ? "start" : "end"), "a")])}
      <div role="progressbar" aria-valuenow={p.m} aria-label={p.text} style={{ ...track, marginTop: 2 }}>
        <div style={{ position: "absolute", top: 0, bottom: 0, left: cover ? "0%" : `${50 - w}%`, width: cover ? "100%" : `${w}%`, background: c, boxShadow: `0 0 8px ${c}aa`, transition: "all .6s ease" }}/>
        <div style={{ position: "absolute", top: -1, bottom: -1, left: "50%", width: 1, background: T.ink }}/>
      </div>
      <div style={{ marginTop: 3, fontSize: 10, color: c, overflowWrap: "anywhere" }}>{p.m > 0 ? "✓ " : ""}{p.text}</div>
    </div>;
  }
  const pct = p.target > 0 ? Math.max(0, Math.min(100, (p.value / p.target) * 100)) : 0;
  return <div>
    {above(p.done || pct >= 100 ? tag(fmt(p.value), 100, c, "end", "v")
      : [tag(fmt(p.value), Math.min(pct, 78), c, "mid", "v"), tag(fmt(p.target), 100, T.ink, "end", "t")])}
    <div role="progressbar" aria-valuenow={p.value} aria-valuemax={p.target} aria-label={`${fmt(p.value)} of ${fmt(p.target)} ${p.unit}`} style={{ ...track, marginTop: 2 }}>
      <div style={{ width: `${pct}%`, height: "100%", background: c, boxShadow: `0 0 8px ${c}aa`, transition: "width .6s ease" }}/>
    </div>
    <div style={{ marginTop: 3, fontSize: 10, color: c, overflowWrap: "anywhere" }}>{fmt(p.value)} / {fmt(p.target)} {p.unit}{p.under ? ` · ${p.text}` : p.done ? " ✓" : ""}</div>
  </div>;
}

// ---------- CASH OUT: a slip bought on Kalshi, sold back at Kalshi's live price ----------
// Straights (and combos with buyers on the book) sell into the order book: the value is what the current bids pay for
// your contracts, after Kalshi's fee. A combo with no book is priced by market makers (an RFQ, kept open while you look).
// One tap sells: all of it at the value shown or better, or nothing.
function CashOut({ sl, kal, onCashed }) {
  const K = sl.kalshi, combo = !!K.combo;
  const ticker = combo ? K.combo.market_ticker : K.orders?.[0]?.ticker;
  const side = combo ? "yes" : K.orders?.[0]?.side === "no" ? "no" : "yes";
  const owned = combo ? Number(K.combo.contracts) || 0 : (K.orders || []).filter(o => o.ticker === ticker).reduce((a, o) => a + (Number(o.filled) || 0), 0);
  const [v, setV] = useState(null), [busy, setBusy] = useState(false), [msg, setMsg] = useState(null), [armed, setArmed] = useState(false);
  const cur = useRef(null), rfq = useRef(null), busyRef = useRef(false);
  // two taps: CASH OUT asks, CONFIRM sells (the ask lapses after 15 seconds so a stale tap can't sell)
  useEffect(() => { if (!armed) return; const t = setTimeout(() => setArmed(false), 15000); return () => clearTimeout(t); }, [armed]);
  const ready = !!kal && kal.env === K.env && !!ticker && owned > 0;
  useEffect(() => {
    if (!ready) return;
    let alive = true, made = null;
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    let pos = null, posAt = 0;
    (async () => {
      while (alive) {
        if (busyRef.current) { await sleep(500); continue; }
        if (typeof document !== "undefined" && document.hidden) { await sleep(2000); continue; }
        // the price as fast as Kalshi gives it: the bids every second; the position itself every 10 seconds
        let wait = 1000;
        try {
          if (!pos || Date.now() - posAt > 10000) { pos = positionOf(await kalshiCall(kal, "GET", `portfolio/positions?ticker=${encodeURIComponent(ticker)}`), ticker); posAt = Date.now(); }
          if (pos.side !== side || !(pos.count > 0)) { cur.current = null; alive && setV({ gone: true }); pos = null; await sleep(15000); continue; }
          const count = Math.round(Math.min(owned, pos.count) * 100) / 100;
          const book = (await kalshiCall({ env: kal.env }, "GET", `markets/${encodeURIComponent(ticker)}/orderbook`)).orderbook_fp;
          const sv = sellValue(book, side, count);
          if (sv.ok) cur.current = { how: "book", count, sv, value: sv.net };
          else if (combo) {
            // no buyers on the combo's book: ask the market makers, and keep the ask open while this card is up
            if (!rfq.current) {
              try { rfq.current = made = (await kalshiCall(kal, "POST", "communications/rfqs", { market_ticker: ticker, contracts_fp: count.toFixed(2), rest_remainder: false, replace_existing: false })).id; }
              catch (e) { const mineR = ((await kalshiCall(kal, "GET", "communications/rfqs?user_filter=self&limit=50").catch(() => ({}))).rfqs || []).find(r => r.market_ticker === ticker && r.status === "open"); if (mineR) rfq.current = mineR.id; else throw e; }
            }
            const best = bestSellQuote((await kalshiCall(kal, "GET", quotesPath(rfq.current))).quotes);
            cur.current = best ? { how: "rfq", count, best, rfq: rfq.current, value: Math.round((count * best.price - feeEstimate(count, best.price)) * 100) / 100 } : { how: "rfq", count, none: true };
          } else cur.current = { how: "book", count, none: true, why: sv.why };
          alive && setV(cur.current);
        } catch (e) { alive && setV(x => ({ ...(x || {}), err: e.message })); }
        await sleep(wait);
      }
    })();
    return () => { alive = false; if (made && !busyRef.current) kalshiCall(kal, "DELETE", `communications/rfqs/${made}`).catch(() => {}); };
  }, [ready, ticker]);
  const settle = async (proceeds, sale) => {
    await api("POST", `slips/${sl.id}/cashout`, { proceeds, sale });
    onCashed(`Cashed out on Kalshi for ${cash(proceeds)} (${sCash(Math.round((proceeds - sl.stake) * 100) / 100)}).`);
  };
  const sell = async () => {
    const want = cur.current;
    if (!want || want.none || busyRef.current) return;
    busyRef.current = true; setBusy(true); setMsg(null); setArmed(false);
    try {
      if (want.how === "book") {
        // the book right now: never sell for less than the value on the button
        const book = (await kalshiCall({ env: kal.env }, "GET", `markets/${encodeURIComponent(ticker)}/orderbook`)).orderbook_fp, now = sellValue(book, side, want.count);
        if (!now.ok || now.net < want.value - 0.005) { if (now.ok) { cur.current = { ...want, sv: now, value: now.net }; setV(cur.current); } setMsg(now.ok ? `The bids just dropped: it's ${cash(now.net)} now. Nothing was sold. Tap again to cash out at the new value.` : `${now.why} Nothing was sold.`); return; }
        const o = await kalshiCall(kal, "POST", "portfolio/events/orders", { ...sellOrder(ticker, side, want.count, want.sv.worst), client_order_id: crypto.randomUUID() });
        const filled = parseFloat(o.fill_count || "0");
        if (!(filled > 0)) { setMsg("The bids moved before it filled, so nothing was sold. The value below is live; tap again."); return; }
        const avgYes = parseFloat(o.average_fill_price || (side === "yes" ? want.sv.worst : 1 - want.sv.worst)), got = side === "yes" ? avgYes : 1 - avgYes;
        const fee = parseFloat(o.average_fee_paid || "0") * filled || feeEstimate(filled, got);
        await settle(Math.round((filled * got - fee) * 100) / 100, { how: "order", order_id: o.order_id, price: got, count: filled });
        return;
      }
      // a maker's quote: sell YES into their YES bid; if they back out, the next one at that price or better
      const floor = want.best.price, tried = new Set(), t0 = Date.now();
      let pick = want.best;
      while (Date.now() - t0 < 20000) {
        if (!pick) { await new Promise(r => setTimeout(r, 500)); pick = bestSellQuote((await kalshiCall(kal, "GET", quotesPath(want.rfq)).catch(() => ({ quotes: [] }))).quotes, { minPrice: floor, skip: tried }); continue; }
        tried.add(pick.quote.id);
        const ok = await kalshiCall(kal, "PUT", `communications/rfqs/${want.rfq}/quotes/${pick.quote.id}/accept`, { accepted_side: "yes" }).then(() => true).catch(() => false);
        const s0 = Date.now();
        while (ok && Date.now() - s0 < 6000) {
          await new Promise(r => setTimeout(r, 600));
          const q = ((await kalshiCall(kal, "GET", quotesPath(want.rfq)).catch(() => ({ quotes: [] }))).quotes || []).find(x => x.id === pick.quote.id);
          if (q?.status === "executed") {
            const real = await kalshiFilled(kal, q.rfq_creator_order_id, "yes");
            const n = real?.count || sellYesContracts(q) || want.count, p = real?.price || parseFloat(q.yes_bid_dollars);
            rfq.current = null;
            await settle(real ? real.net : Math.round((n * p - feeEstimate(n, p)) * 100) / 100, { how: "rfq", quote_id: q.id, price: p, count: n });
            return;
          }
          if (!q || q.status === "cancelled") break;
        }
        pick = null;
      }
      setMsg(`No maker would take it at ${cents(floor)} or better just now, so nothing was sold. The value below is live.`);
    } catch (e) { setMsg(`Kalshi: ${e.message} Nothing was sold.`); }
    finally { busyRef.current = false; setBusy(false); }
  };
  const box = { marginTop: 8, paddingTop: 8, borderTop: `1px solid ${T.line}` };
  if (!ready) return <div style={{ ...box, fontSize: 11, color: T.dim, lineHeight: 1.5 }}>{!kal ? "Connect your Kalshi key in Tools → Kalshi to cash out." : kal.env !== K.env ? `This slip was bought on Kalshi ${K.env === "demo" ? "demo" : "live"}; your key here is for ${kal.env}.` : "Couldn't read this slip's Kalshi position."}</div>;
  const val = v && !v.none && !v.gone && v.value != null ? v.value : null, pl = val != null ? Math.round((val - sl.stake) * 100) / 100 : null;
  return <div style={box}>
    <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr)", gap: 8 }}>
      <div style={{ minWidth: 0, fontSize: 12, color: T.dim, lineHeight: 1.5 }}>
        <div>Cash out now {val != null ? <><b style={{ color: "#fff" }}>{cash(val)}</b> <span style={{ color: pl > 0 ? NEON.green : pl < 0 ? NEON.red : T.dim }}>({sCash(pl)})</span></> : null}</div>
        <div style={{ fontSize: 10, color: T.faint, overflowWrap: "anywhere" }}>{!v ? "Reading Kalshi…" : v.gone ? "This position isn't open on Kalshi anymore (sold or settled there)." : v.none ? (v.how === "rfq" ? "Asking Kalshi's market makers for a price…" : v.why || "No bids on Kalshi right now.") : `${v.count} contracts · ${v.how === "rfq" ? "market maker's price" : "Kalshi's live bids"}, after fees · live`}{v?.err ? ` · couldn't refresh: ${v.err}` : ""}</div>
      </div>
      {!armed || busy ? <button onClick={() => { setMsg(null); setArmed(true); }} disabled={val == null || busy} aria-label="cash out" style={{ ...btnStyle(val != null && !busy), width: "100%", padding: "11px 12px", borderColor: val != null && !busy ? NEON.gold : T.line, background: val != null && !busy ? "rgba(255,194,38,.14)" : "none", color: val != null && !busy ? NEON.gold : T.faint, whiteSpace: "nowrap" }}>{busy ? "SELLING ON KALSHI…" : val != null ? `CASH OUT ${cash(val)}` : "CASH OUT"}</button>
        : <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 8 }}>
          <button onClick={sell} disabled={val == null} aria-label="confirm cash out" style={{ ...btnStyle(val != null), padding: "11px 8px", borderColor: NEON.gold, background: "rgba(255,194,38,.32)", color: "#fff", fontWeight: 700, overflowWrap: "anywhere" }}>{val != null ? `CONFIRM CASH OUT ${cash(val)}` : "CONFIRM CASH OUT"}</button>
          <button onClick={() => setArmed(false)} aria-label="cancel cash out" style={{ ...btnStyle(false), padding: "11px 12px", color: T.dim, cursor: "pointer", whiteSpace: "nowrap" }}>CANCEL</button>
        </div>}
    </div>
    {msg && <div style={{ marginTop: 6, fontSize: 11, color: NEON.gold, lineHeight: 1.5 }}>{msg}</div>}
  </div>;
}

// ---------- live legs: the scores and, for games with a player prop riding, the box score, every 30 seconds ----------
// (LIVE TICKETS and MY BETS): which game each leg is on, whether a slip is live, and each leg's progress
function useLegTrack(slips, on) {
  const [scores, setScores] = useState(null), [boxes, setBoxes] = useState(() => new Map()), ref = useRef(slips);
  ref.current = slips;
  useEffect(() => {
    if (!on) return;
    let alive = true, timer = null;
    const tick = async () => {
      if (typeof document !== "undefined" && document.hidden) { timer = setTimeout(tick, 15000); return; }
      try {
        _betRows = null;
        const b = await loadBetRows();
        if (!alive) return;
        setScores(new Map(b.rows.map(r => [`${r.sport}|${r.id}`, r])));
        const games = new Map();
        for (const t of ref.current || []) for (const l of t.legs || []) { const p = !l.res && propOf(l), r = p && gameFor(b.rows, p.sport, p.teams); if (r && (r.state === "in" || r.state === "post")) games.set(`${r.sport}|${r.id}`, r); }
        const got = await Promise.all([...games.values()].map(r => getJSON(summaryUrl(r.sport, r.league, r.id)).then(j => [`${r.sport}|${r.id}`, parseFinal(j, r.sport)]).catch(() => null)));
        if (alive && got.some(Boolean)) setBoxes(m => { const n = new Map(m); for (const x of got) if (x) n.set(x[0], x[1]); return n; });
      } catch (_) { /* next pass */ }
      if (alive) timer = setTimeout(tick, 30000);
    };
    tick();
    return () => { alive = false; clearTimeout(timer); };
  }, [on, !!slips]);
  const rowsArr = useMemo(() => (scores ? [...scores.values()] : []), [scores]);
  const gameOf = l => { const p = propOf(l) || kalshiGameLeg(l); return p ? gameFor(rowsArr, p.sport, p.teams) : scores?.get(`${l.sport}|${l.eventId}`) || null; };
  const isLiveNow = t => t.status === "pending" && (t.live || t.legs.some(l => !l.res && (Date.parse(l.date) <= Date.now() || gameOf(l)?.state === "in")));
  const track = l => { const r = gameOf(l); return r ? legProgress(l, r, propOf(l) ? boxes.get(`${r.sport}|${r.id}`) : null) : null; };
  return { scores, gameOf, isLiveNow, track };
}

// ---------- everyone's tickets: LIVE (riding now or later today, tail any of them) and PAST (every settled ticket) ----------
const etDayOf = iso => new Date(iso).toLocaleDateString("en-CA", { timeZone: "America/New_York" });
function Tickets({ kind, onOpen, kal = null, onTools, onTailed, onCashed }) {
  const [tailing, setTailing] = useState(null);              // the ticket being tailed: its slip opens right under it
  const [d, setD] = useState(null), [err, setErr] = useState(null), [st, setSt] = useState("all"), [busy, setBusy] = useState(false);
  const q = s => `tickets/${kind}${kind === "past" && s !== "all" ? `?status=${s}` : ""}`;
  const { scores, gameOf, isLiveNow, track: trackLeg } = useLegTrack(d?.tickets, kind === "live");
  useEffect(() => {
    let on = true, timer = null;
    const pull = async () => {
      if (typeof document !== "undefined" && document.hidden) { timer = setTimeout(pull, 20000); return; }
      try { const j = await api("GET", q(st)); if (on) { setD(j); setErr(null); } } catch (e) { if (on) setErr(e.message); }
      if (kind === "live") timer = setTimeout(pull, 60000);
    };
    setD(null); pull();
    return () => { on = false; clearTimeout(timer); };
  }, [kind, st]);
  const more = async () => { setBusy(true); try { const j = await api("GET", `${q(st)}${st === "all" ? "?" : "&"}before=${encodeURIComponent(d.tickets.at(-1).settled)}`); setD({ ...d, tickets: [...d.tickets, ...j.tickets], more: j.more }); } catch (e) { setErr(e.message); } finally { setBusy(false); } };
  if (err && !d) return <Panel color={NEON.red}><div style={{ fontSize: 13, color: "#FF8095" }}>{err}</div></Panel>;
  const head = t => {
    const open = kind === "live" && t.legs.some(l => !l.res);       // anything still riding, upcoming or live
    return <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 10, alignItems: "center", paddingBottom: 8, marginBottom: 8, borderBottom: `1px solid ${T.line}` }}>
      <div style={{ minWidth: 0 }}>
        <button onClick={() => onOpen(t.username)} style={{ maxWidth: "100%", padding: 0, border: "none", background: "none", color: t.you ? T.chrome : "#fff", fontFamily: F.d, fontSize: 13, fontWeight: 700, letterSpacing: 0.5, cursor: "pointer", textAlign: "left", overflowWrap: "anywhere" }}>{t.username}{t.you ? <span style={{ fontFamily: F.m, fontSize: 11, fontWeight: 400, color: T.dim }}> · you</span> : null}</button>
        {(t.tails > 0 || t.tailOf) && <div style={{ fontSize: 10, color: T.faint, marginTop: 2, lineHeight: 1.5, overflowWrap: "anywhere" }}>{t.tails > 0 ? <span style={{ color: NEON.gold }}>{t.tails} tailing</span> : null}{t.tails > 0 && t.tailOf ? " · " : ""}{t.tailOf ? `tailed ${t.tailOf}` : ""}</div>}
      </div>
      {open ? <button onClick={() => setTailing(tailing?.id === t.id ? null : { id: t.id, from: t.you ? "your own ticket" : t.username, legs: t.legs.filter(l => !l.res), left: t.legs.filter(l => l.res).length })} aria-pressed={tailing?.id === t.id} aria-label={`tail ${t.you ? "your ticket" : t.username}`} style={{ ...btnStyle(), borderColor: NEON.gold, background: tailing?.id === t.id ? "rgba(255,194,38,.3)" : "rgba(255,194,38,.12)", color: tailing?.id === t.id ? "#fff" : NEON.gold, whiteSpace: "nowrap" }}>{tailing?.id === t.id ? "TAIL ▾" : "TAIL ▸"}</button> : <span/>}
    </div>;
  };
  const card = t => <Fragment key={t.id}>
    <SlipCard sl={t} top={head(t)} liveRows={kind === "live" ? scores : null} track={kind === "live" && isLiveNow(t) ? trackLeg : null} gameOfLeg={kind === "live" ? gameOf : null}
      foot={kind === "live" && isLiveNow(t) && t.status === "pending" && t.kalshi ? (t.you ? <CashOut sl={t} kal={kal} onCashed={m => onCashed && onCashed(m)}/> : <CashValue sl={t}/>) : null}/>
    {kind === "live" && tailing?.id === t.id && <NewSlip key={`tail${t.id}`} seed={tailing} onUnseed={() => setTailing(null)} kal={kal} onTools={onTools} onPlaced={msg => { setTailing(null); onTailed && onTailed(msg); }}/>}
  </Fragment>;
  if (kind === "live") {
    const today = etDayOf(new Date().toISOString()), list = d?.tickets || [];
    const groups = [["LIVE NOW", list.filter(isLiveNow)], ["LATER TODAY", []], ["UPCOMING", []]];
    for (const t of list) if (!groups[0][1].includes(t)) (t.next && etDayOf(t.next) === today ? groups[1][1] : groups[2][1]).push(t);
    return <>
      <div style={{ marginTop: 14, fontSize: 11, color: T.dim, lineHeight: 1.6 }}>Everyone's tickets that are still riding. Tap <span style={{ color: NEON.gold }}>TAIL ▸</span> on any ticket to bet the same picks right here, upcoming or live (live games go through Kalshi). Updates every minute.</div>
      {!d && <Panel><div style={{ fontSize: 12, color: T.dim }}>Loading tickets…</div></Panel>}
      {d && !list.length && <Panel><div style={{ fontSize: 12, color: T.dim }}>No tickets riding right now.</div></Panel>}
      {d && groups.filter(([, g]) => g.length).map(([title, g]) => <Panel key={title} title={title} right={`${g.length} ticket${g.length > 1 ? "s" : ""}`} color={title === "LIVE NOW" ? NEON.red : T.chrome}>{g.map(card)}</Panel>)}
    </>;
  }
  const tot = d?.totals;
  return <>
    <div role="group" aria-label="filter past tickets" style={{ display: "grid", gridTemplateColumns: "repeat(5,minmax(0,1fr))", marginTop: 14, border: `1px solid ${T.line}` }}>
      {[["all", "ALL"], ["won", "WON"], ["lost", "LOST"], ["cashed", "CASHED"], ["push", "PUSH"]].map(([k, t]) => <button key={k} onClick={() => setSt(k)} aria-pressed={st === k} style={{ padding: "8px 2px", border: "none", background: st === k ? "rgba(143,0,255,0.3)" : "none", color: st === k ? "#fff" : T.dim, fontFamily: F.d, fontSize: 11, letterSpacing: 1, cursor: "pointer" }}>{t}</button>)}
    </div>
    <Panel title="PAST TICKETS" right={tot ? <span>site <b style={{ color: T.ink }}>{tot.W}-{tot.L}{tot.P ? `-${tot.P}` : ""}</b> · <span style={{ color: tot.net > 0 ? NEON.green : tot.net < 0 ? NEON.red : T.dim }}>{sCash(tot.net)}</span></span> : null}>
      {!d && <div style={{ fontSize: 12, color: T.dim }}>Grading and loading…</div>}
      {d && !d.tickets.length && <div style={{ fontSize: 12, color: T.dim }}>No {st === "all" ? "settled" : st} tickets yet.</div>}
      {d && d.tickets.map(card)}
      {d?.more && <button onClick={more} disabled={busy} style={{ ...btnStyle(!busy), width: "100%", marginTop: 12 }}>{busy ? "LOADING…" : "LOAD MORE"}</button>}
      {err && d && <div style={{ fontSize: 12, color: "#FF8095", marginTop: 8 }}>{err}</div>}
    </Panel>
  </>;
}

// ---------- leaderboards: by record ("5 for 7") and by money ----------
function Leaderboard({ onOpen }) {
  const [d, setD] = useState(null), [err, setErr] = useState(null);
  useEffect(() => { api("GET", "board").then(setD).catch(e => setErr(e.message)); }, []);
  if (err) return <Panel color={NEON.red}><div style={{ fontSize: 13, color: "#FF8095" }}>{err}</div></Panel>;
  if (!d) return <Panel><div style={{ fontSize: 12, color: T.dim }}>Grading and loading…</div></Panel>;
  const row = (p, i, right, sub) => <button key={p.username} onClick={() => onOpen(p.username)} style={{ display: "grid", gridTemplateColumns: "26px minmax(0,1fr) auto", gap: 10, alignItems: "center", width: "100%", padding: "10px 4px", border: "none", borderTop: i ? `1px solid ${T.line}` : "none", background: p.you ? "rgba(143,0,255,.14)" : "none", cursor: "pointer", textAlign: "left", fontFamily: F.m }}>
    <span style={{ fontFamily: F.d, fontSize: 14, fontWeight: 700, color: i === 0 ? NEON.gold : i === 1 ? NEON.silver : i === 2 ? "#E08A4F" : T.dim, textAlign: "center" }}>{i + 1}</span>
    <div style={{ minWidth: 0 }}>
      <div style={{ ...oneLine, fontSize: 13, color: "#fff" }}>{p.username}</div>
      <div style={{ fontSize: 10, color: T.faint, lineHeight: 1.5, marginTop: 1 }}>{p.you ? <span style={{ color: T.chrome }}>you · </span> : null}{sub}</div>
    </div>
    <span style={{ fontFamily: F.d, fontSize: 15, fontWeight: 700, whiteSpace: "nowrap", color: right.c }}>{right.v}</span>
  </button>;
  return <>
    <Panel title="BY RECORD" right="win %, then wins">
      {!d.record.length && <div style={{ fontSize: 12, color: T.dim }}>No graded bets yet. The board fills in as games finish.</div>}
      {d.record.map((p, i) => row(p, i, { v: `${p.W}-${p.L}`, c: T.ink }, `${pctTxt(p.pct)} · ${p.W} for ${p.W + p.L}${p.P ? ` · ${p.P} push` : ""}${p.streak ? ` · streak ${p.streak}` : ""}`))}
    </Panel>
    <Panel title="BY MONEY" right="net winnings">
      {!d.money.length && <div style={{ fontSize: 12, color: T.dim }}>No graded bets yet.</div>}
      {d.money.map((p, i) => row(p, i, { v: sCash(p.net), c: p.net > 0 ? NEON.green : p.net < 0 ? NEON.red : T.ink }, `won ${cash(p.won)} · ROI ${p.roi != null ? `${p.roi > 0 ? "+" : ""}${(p.roi * 100).toFixed(1)}%` : "–"}`))}
    </Panel>
    {d.waiting.length > 0 && <div style={{ fontSize: 11, color: T.faint, marginTop: 10, lineHeight: 1.6 }}>Not ranked yet (no graded bets): {d.waiting.join(", ")}</div>}
  </>;
}

// ─── FINAL REPORT: tap a finished game. Score by period, a rundown from the numbers, the algo's pre-game call and
// what it learned, team stats, how it was scored, and every player's line. ──────────────────────────────────────
const keepScores = t => String(t).replace(/(\d)-(\d)/g, "$1\u2060-\u2060$2");   // a score like 21-14 never splits across lines
const initialName = n => { const p = String(n || "").trim().split(/\s+/); return p.length > 1 ? `${p[0][0]}. ${p.slice(1).join(" ")}` : n; };
async function trackRecordFor(sport, row) {
  const day = etISO(row.date), f = await dataFile(`track/${sport}/${day.slice(0, 7)}.json`), gs = f?.games || {};
  if (isIndiv(sport)) return Object.values(gs).find(g => String(g.eid) === String(row.id)) || null;
  const hit = gs[`${sport}|${day}|${row.away.abbr}@${row.home.abbr}`] || Object.values(gs).find(g => g.day === day && g.away.abbr === row.away.abbr && g.home.abbr === row.home.abbr) || null;
  if (hit || !row.slug) return hit;
  // not in the log yet: rebuild the call from pre-game data now (the background tracker logs the same rebuild)
  const rec = await reconstructCall(sport, row.slug, row.id, ymd(new Date(row.date))).catch(() => null);
  if (!rec) return null;
  const { as, hs } = rec.final, out = { ...rec, fresh: true, result: { as, hs, at: Date.now() } };
  out.plays = out.plays.map(pl => ({ ...pl, ...gradePlay(pl, as, hs) }));
  return out;
}
// tennis / MMA have no summary route: the board row is the report
function indivFinal(sport, row) {
  const sa = String(row.away.score || "").split(" ").filter(Boolean).map(Number), sh = String(row.home.score || "").split(" ").filter(Boolean).map(Number);
  const won = (x, y) => x.reduce((k, v, i) => k + (v > (y[i] ?? -1) ? 1 : 0), 0);
  const W = row.away.win ? "away" : row.home.win ? "home" : null;
  const setText = sa.length ? sa.map((v, i) => (W === "home" ? `${sh[i]}-${v}` : `${v}-${sh[i]}`)).join(", ") : "";
  const rs = row.state === "in" ? readSets(row.away.score, row.home.score, true) : null;     // live: only finished sets count
  const t = (x, s, o, k) => ({ id: "", abbr: "", name: x.name, short: x.name, score: rs ? rs[k] : sa.length ? won(s, o) : null, win: !!x.win, rec: "", lines: s });
  return { sport, id: row.id, detail: row.detail || "Final", done: true, away: t(row.away, sa, sh, "sa"), home: t(row.home, sh, sa, "sb"), venue: "", city: "", attendance: null,
    teamStats: [], players: { away: [], home: [] }, leaders: { away: [], home: [] }, scoring: [], lines: null, wp: null, setText: setText ? `in ${sport === "Tennis" ? "sets" : "rounds"}: ${setText}` : "" };
}
function FinalScreen({ sport, row: row0, onBack, live = false, onSim }) {
  const [d, setD] = useState(null), [err, setErr] = useState(null), [side, setSide] = useState("away"), [row, setRow] = useState(row0), [at, setAt] = useState(null);
  useEffect(() => {
    let on = true, timer = null;
    const pull = async () => {
      if (live && typeof document !== "undefined" && document.hidden) { timer = setTimeout(pull, 15000); return; }
      let F = null, r = row0, ended = false;
      if (isIndiv(sport)) {                                // tennis / MMA: the board row is the box score; re-read it while live
        if (live) { try { const j = await board(sport, row0.slug, ymd(new Date(row0.date))); r = liveBoard(j, sport).find(x => x.id === row0.id) || row0; } catch (_) { /* keep the last */ } }
        F = indivFinal(sport, r); ended = r.state === "post";
      } else { const j = await getJSON(summaryUrl(sport, row0.slug, row0.id)).catch(() => null); F = j ? parseFinal(j, sport) : null; ended = !!F?.done; }
      if (!on) return;
      if (!F) { if (!d) setErr("Couldn't load this game's box score from the scores routes. Retrying."); if (live) timer = setTimeout(pull, 30000); return; }
      setErr(null); setRow(r);
      if (live) setD({ F, live: !ended });
      else { const rec = await trackRecordFor(sport, r).catch(() => null); if (on) setD({ F, rec, R: finalRundown(F, sport, rec, LEARNED), review: algoReview(F, sport, rec, LEARNED) }); }
      setAt(new Date());
      if (live && !ended) timer = setTimeout(pull, 30000);
    };
    pull();
    return () => { on = false; clearTimeout(timer); };
  }, [sport, row0.id, live]);
  const cfg = SPORT_CFG[sport], isLive = live && d?.live !== false;
  return <Shell status={live ? (isLive ? "live box score" : "final") : "final report"}>
    <div style={{ display: "grid", gridTemplateColumns: "auto minmax(0,1fr)", alignItems: "center", gap: 12, marginTop: 16 }}>
      <button onClick={onBack} style={btnStyle()}>◂ BACK</button>
      <div style={{ textAlign: "right", fontFamily: F.d, fontSize: "clamp(14px,4vw,18px)", letterSpacing: 3, color: "#fff", textShadow: `0 0 14px ${(live ? NEON.red : NEON.green)}66` }}>{live ? "BOX SCORE" : "FINAL REPORT"}</div>
    </div>
    {live && <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 10, alignItems: "center", marginTop: 12, fontSize: 11, color: T.dim }}>
      <span>{isLive ? <><span style={{ color: NEON.red, animation: "blink 1.6s infinite" }}>●</span> Live · updates every 30 seconds{at ? ` · last ${at.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", second: "2-digit" })}` : ""}</> : "This game is over."}</span>
      {onSim && isLive && <button onClick={onSim} style={{ ...btnStyle(), whiteSpace: "nowrap" }}>SIMULATE ▸</button>}
    </div>}
    {err && <Panel color={NEON.red}><div style={{ fontSize: 13, color: "#FF8095" }}>{err}</div></Panel>}
    {!d && !err && <Panel><div style={{ fontSize: 12, color: T.dim }}>Loading the box score…</div></Panel>}
    {d && <>
      <ScorePanel F={d.F} sport={sport} row={row} live={isLive}/>
      {!live && <><Panel title="GAME RUNDOWN" right={cfg.label}>
        {d.R.paras.map((p, i) => <p key={i} style={{ margin: i ? "10px 0 0" : 0, fontSize: 13, lineHeight: 1.7, color: T.ink }}>{keepScores(p)}</p>)}
      </Panel>
      <Panel title="THE ALGO'S CALL" right={d.rec?.late ? (d.rec.fresh ? "rebuilt from pre-game data" : "rebuilt · graded") : d.rec?.result ? "graded" : d.rec ? "grading soon" : "no call"} color={T.chrome}>
        {d.rec && <AlgoTiles F={d.F} rec={d.rec} sport={sport}/>}
        {d.review?.length ? <ReviewSections sections={d.review}/>
          : d.R.algo.map((p, i) => <p key={i} style={{ margin: i || d.rec ? "10px 0 0" : 0, fontSize: 12, lineHeight: 1.7, color: i === d.R.algo.length - 1 && /^What it learns/.test(p) ? T.chrome : T.ink }}>{keepScores(p)}</p>)}
      </Panel></>}
      {teamStatRows(d.F, sport).length > 0 && <TeamStatsPanel F={d.F} sport={sport}/>}
      {d.F.scoring.length > 0 && !["NBA", "WNBA", "CBB", "CBBW"].includes(sport) && <ScoringPanel F={d.F} sport={sport}/>}
      {(d.F.players.away.length > 0 || d.F.players.home.length > 0) && <Panel title="PLAYER STATS" right="tap a player for every stat">
        <div style={{ display: "grid", gridTemplateColumns: "repeat(2,minmax(0,1fr))", border: `1px solid ${T.line}` }}>
          {[["away", d.F.away], ["home", d.F.home]].map(([k, t]) => <button key={k} onClick={() => setSide(k)} style={{ padding: "10px 6px", border: "none", borderBottom: `2px solid ${side === k ? T.chrome : "transparent"}`, background: side === k ? "rgba(143,0,255,0.18)" : "none", color: side === k ? "#fff" : T.dim, fontFamily: F.d, fontSize: 12, letterSpacing: 1, cursor: "pointer", overflowWrap: "anywhere" }}>{t.abbr || initialName(t.name)}</button>)}
        </div>
        {d.F.players[side].map((g, i) => <BoxTable key={`${side}${i}`} g={g} sport={sport}/>)}
        {!d.F.players[side].length && <div style={{ fontSize: 12, color: T.dim, marginTop: 10 }}>No player stats posted for this side.</div>}
      </Panel>}
    </>}
  </Shell>;
}
function ScorePanel({ F: G, sport, row, live = false }) {
  const A = G.away, H = G.home, n = Math.max(A.lines.length, H.lines.length), mlb = sport === "MLB", ind = isIndiv(sport);
  const extra = mlb ? [["R", "score"], ["H", "hits"], ["E", "errors"]] : [["T", "score"]];
  const cols = `minmax(44px,auto) repeat(${n},minmax(0,1fr))${ind ? "" : ` repeat(${extra.length},minmax(22px,auto))`}`;
  const cell = (v, bold, c) => <span style={{ textAlign: "center", fontFamily: F.d, fontSize: 12, fontWeight: bold ? 700 : 500, color: c || (bold ? "#fff" : T.dim), whiteSpace: "nowrap" }}>{v ?? ""}</span>;
  const team = (t, k) => <div key={k} style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 12, alignItems: "center", padding: "6px 0" }}>
    <div style={{ minWidth: 0 }}>
      <div style={{ fontFamily: F.d, fontSize: 15, fontWeight: 700, color: t.win || live ? "#fff" : T.dim, overflowWrap: "anywhere" }}>{t.abbr ? <>{t.abbr} <span style={{ fontFamily: F.m, fontSize: 12, fontWeight: 400, color: T.dim }}>{t.name}</span></> : t.name}{t.win && !live && <span style={{ color: NEON.green }}> ✓</span>}</div>
      {t.rec && <div style={{ fontSize: 11, color: T.faint, marginTop: 2 }}>{t.rec}</div>}
    </div>
    <span style={{ fontFamily: F.d, fontSize: 30, fontWeight: 900, color: t.win || live ? "#fff" : T.dim, textShadow: live ? `0 0 12px ${NEON.red}55` : t.win ? `0 0 12px ${NEON.green}66` : "none" }}>{t.score ?? ""}</span>
  </div>;
  return <Panel title={live ? `● LIVE · ${String(row.detail || G.detail || "").toUpperCase()}` : `FINAL${G.detail && !/^(final|ft)$/i.test(G.detail) ? ` · ${G.detail.replace(/^final\s*\/?\s*/i, "").toUpperCase()}` : ""}`} right={[ind || manyLeagues(sport) ? row.league : cfgLabel(sport), etDayLabel(row.date)].filter(Boolean).join(" · ")} color={live ? NEON.red : NEON.green}>
    {team(A, "a")}{team(H, "h")}
    {n > 0 && <div style={{ marginTop: 10, borderTop: `1px solid ${T.line}`, paddingTop: 10, display: "grid", gridTemplateColumns: cols, rowGap: 6, columnGap: 4, alignItems: "center" }}>
      <span style={{ fontSize: 10, color: T.faint }}>{ind ? (sport === "Tennis" ? "SET" : "RD") : ""}</span>
      {Array.from({ length: n }, (_, i) => <span key={i} style={{ textAlign: "center", fontSize: 10, color: T.faint }}>{i + 1}</span>)}
      {!ind && extra.map(([l]) => <span key={l} style={{ textAlign: "center", fontSize: 10, color: T.faint }}>{l}</span>)}
      {[A, H].map((t, r) => [
        <span key={`n${r}`} style={{ fontFamily: F.d, fontSize: 11, color: t.win ? "#fff" : T.dim, overflowWrap: "anywhere" }}>{t.abbr || initialName(t.name).split(" ").slice(-1)[0]}</span>,
        ...Array.from({ length: n }, (_, i) => <Fragment key={`c${r}${i}`}>{cell(t.lines[i], false)}</Fragment>),
        ...(!ind ? extra.map(([l, f]) => <Fragment key={`e${r}${l}`}>{cell(t[f], l === "R" || l === "T", t.win && (l === "R" || l === "T") ? "#fff" : undefined)}</Fragment>) : []),
      ])}
    </div>}
  </Panel>;
}
const cfgLabel = sp => SPORT_CFG[sp]?.label || sp;
// the post-game review, section by section (mirrors the pre-game rundown); the first and last sections open by default
function ReviewSections({ sections }) {
  const [open, setOpen] = useState(() => ({ 0: true, [sections.length - 1]: true }));
  return <div style={{ display: "grid", gap: 6, marginTop: 12 }}>
    {sections.map((x, i) => <div key={i} style={{ border: `1px solid ${T.line}`, background: "rgba(9,2,17,.45)" }}>
      <button onClick={() => setOpen(o => ({ ...o, [i]: !o[i] }))} style={{ width: "100%", display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 8, alignItems: "center", padding: "9px 10px", border: "none", background: "none", color: open[i] ? "#fff" : T.ink, fontFamily: F.d, fontSize: 11, letterSpacing: 1.5, textAlign: "left", cursor: "pointer" }}>
        <span>{x.title.toUpperCase()}</span><span style={{ color: T.chrome }}>{open[i] ? "▴" : "▾"}</span>
      </button>
      {open[i] && <div style={{ padding: "0 10px 10px" }}>{x.body.split("\n\n").map((p, k) => <p key={k} style={{ margin: k ? "8px 0 0" : 0, fontSize: 12, lineHeight: 1.7, color: T.ink }}>{keepScores(p)}</p>)}</div>}
    </div>)}
  </div>;
}
function AlgoTiles({ F: G, rec, sport }) {
  const tot = rec.p.a + rec.p.h + (rec.p.d || 0), pH = rec.p.h / tot, pA = rec.p.a / tot, W = G.away.win ? "away" : G.home.win ? "home" : null;
  const likes = pH >= pA ? "home" : "away", right = W && W === likes;
  const proj = rec.proj && rec.proj.total > 0 ? { h: (rec.proj.total + rec.proj.margin) / 2, a: (rec.proj.total - rec.proj.margin) / 2 } : null;
  const pick = rec.pick ? rec.plays.find(x => x.key === rec.pick) : null;
  const lab = t => t.abbr || initialName(t.name).split(" ").slice(-1)[0];
  const tiles = [
    ["WINNER CALL", `${lab(likes === "home" ? G.home : G.away)} ${Math.round(Math.max(pH, pA) * 100)}%`, W ? (right ? NEON.green : NEON.red) : T.ink, W ? (right ? "right" : "wrong") : ""],
    proj ? ["PROJECTED", `${lab(G.away)} ${proj.a.toFixed(1)} – ${lab(G.home)} ${proj.h.toFixed(1)}`, T.ink, `actual ${G.away.score}-${G.home.score}`] : null,
    pick ? ["ITS PICK", pick.label, pick.res === "W" ? NEON.green : pick.res === "L" ? NEON.red : T.ink, pick.res ? (pick.res === "W" ? "won" : pick.res === "L" ? "lost" : "push") : "grading"] : ["ITS PICK", "no bet", T.dim, "nothing cleared the bar"],
  ].filter(Boolean);
  return <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(150px,1fr))", gap: 8 }}>
    {tiles.map(([k, v, c, sub]) => <div key={k} style={{ minWidth: 0, border: `1px solid ${T.line}`, background: "rgba(9,2,17,.5)", padding: "9px 10px" }}>
      <div style={{ fontSize: 10, color: T.faint, letterSpacing: 1 }}>{k}</div>
      <div style={{ fontFamily: F.d, fontSize: 13, fontWeight: 700, color: c, marginTop: 4, overflowWrap: "anywhere", lineHeight: 1.35 }}>{v}</div>
      {sub && <div style={{ fontSize: 10, color: T.dim, marginTop: 3 }}>{sub}</div>}
    </div>)}
  </div>;
}
function TeamStatsPanel({ F: G, sport }) {
  const rows = teamStatRows(G, sport), lab = t => t.abbr || initialName(t.name);
  return <Panel title="TEAM STATS" right={`${lab(G.away)} · ${lab(G.home)}`}>
    {rows.map((r, i) => <div key={r.key} style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) minmax(0,1.6fr) minmax(0,1fr)", gap: 8, alignItems: "baseline", padding: "6px 0", borderTop: i ? `1px solid ${T.line}` : "none" }}>
      <span style={{ fontFamily: F.d, fontSize: 13, color: AWAY_DEF, overflowWrap: "anywhere" }}>{r.a}</span>
      <span style={{ fontSize: 11, color: T.dim, textAlign: "center", lineHeight: 1.4 }}>{r.label}</span>
      <span style={{ fontFamily: F.d, fontSize: 13, color: HOME_DEF, textAlign: "right", overflowWrap: "anywhere" }}>{r.h}</span>
    </div>)}
  </Panel>;
}
function ScoringPanel({ F: G, sport }) {
  const lab = s => (s === "away" ? G.away.abbr || G.away.short : G.home.abbr || G.home.short);
  const per = sport === "NHL" ? "P" : sport === "MLB" ? "" : "Q";
  return <Panel title={sport === "Soccer" ? "GOALS & CARDS" : "SCORING"} right={`${G.scoring.length} ${sport === "Soccer" ? "events" : "plays"}`}>
    {G.scoring.map((e, i) => <div key={i} style={{ display: "grid", gridTemplateColumns: "auto auto minmax(0,1fr)", gap: 10, alignItems: "baseline", padding: "6px 0", borderTop: i ? `1px solid ${T.line}` : "none" }}>
      <span style={{ fontFamily: F.d, fontSize: 11, color: e.side === "away" ? AWAY_DEF : HOME_DEF, whiteSpace: "nowrap" }}>{lab(e.side)}</span>
      <span style={{ fontSize: 11, color: T.faint, whiteSpace: "nowrap" }}>{sport === "Soccer" ? e.when : `${e.period ? (per ? `${per}${e.period}` : ord2(e.period)) : ""}${e.when ? ` ${e.when}` : ""}`}</span>
      <span style={{ fontSize: 12, color: T.ink, lineHeight: 1.5, overflowWrap: "anywhere" }}>{sport === "Soccer" ? `${e.kind === "red card" ? "🟥 " : "⚽ "}${e.who}${e.kind === "own goal" ? " (own goal)" : e.kind === "penalty" ? " (pen)" : e.kind === "penalty missed" ? " (pen missed)" : ""}` : e.text}{e.as != null && e.hs != null ? <span style={{ color: T.dim }}> · {e.as}-{e.hs}</span> : null}</span>
    </div>)}
  </Panel>;
}
const ord2 = k => `${k}${k % 100 >= 11 && k % 100 <= 13 ? "th" : { 1: "st", 2: "nd", 3: "rd" }[k % 10] || "th"}`;
// one stat group: as many columns as fit the screen, most telling first; tap a player for the full line
function BoxTable({ g, sport }) {
  const ref = useRef(null), [w, setW] = useState(360), [open, setOpen] = useState(null);
  useEffect(() => { const el = ref.current; if (!el) return; const fit = () => setW(el.clientWidth || 360); fit(); if (typeof ResizeObserver === "undefined") return; const ro = new ResizeObserver(fit); ro.observe(el); return () => ro.disconnect(); }, []);
  const order = colOrder(sport, g.name, g.labels);
  const width = i => Math.ceil(Math.max(String(g.labels[i]).length, ...g.rows.map(r => String(r.stats[i] ?? "").length), g.totals ? String(g.totals[i] ?? "").length : 0) * 7.3 + 8);
  const nameMin = w < 400 ? 104 : 140, gap = 4;
  const shown = [];
  let used = nameMin;
  for (const i of order) { const cw = width(i); if (used + cw + gap > w) break; shown.push(i); used += cw + gap; }
  const cols = `minmax(${nameMin}px,1fr) ${shown.map(i => `${width(i)}px`).join(" ")}`;
  const hidden = order.length - shown.length;
  return <div ref={ref} style={{ marginTop: 14 }}>
    <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 8, alignItems: "baseline", marginBottom: 6 }}>
      <span style={{ fontFamily: F.d, fontSize: 11, letterSpacing: 2, color: T.chrome }}>{groupTitle(g.name).toUpperCase()}</span>
      {hidden > 0 && <span style={{ fontSize: 10, color: T.faint }}>+{hidden} more per player</span>}
    </div>
    <div style={{ display: "grid", gridTemplateColumns: cols, columnGap: gap, fontSize: 10, color: T.faint, padding: "0 0 4px", borderBottom: `1px solid ${T.line}` }}>
      <span/>{shown.map(i => <span key={i} style={{ textAlign: "right" }}>{g.labels[i]}</span>)}
    </div>
    {g.rows.map((r, k) => <div key={k}>
      <button onClick={() => setOpen(open === k ? null : k)} style={{ display: "grid", gridTemplateColumns: cols, columnGap: gap, alignItems: "baseline", width: "100%", padding: "6px 0", border: "none", borderBottom: `1px solid ${T.line}`, background: open === k ? "rgba(143,0,255,.12)" : "none", cursor: "pointer", textAlign: "left", fontFamily: F.m }}>
        <span style={{ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", fontSize: 12, color: r.starter ? "#fff" : T.ink }}>{initialName(r.name)}{r.pos && <span style={{ color: T.faint, fontSize: 10 }}> {r.pos}</span>}</span>
        {shown.map(i => <span key={i} style={{ textAlign: "right", fontSize: 12, color: T.ink, fontVariantNumeric: "tabular-nums" }}>{r.stats[i]}</span>)}
      </button>
      {open === k && <div style={{ padding: "8px 0 10px", borderBottom: `1px solid ${T.line}` }}>
        <div style={{ fontSize: 12, color: "#fff", marginBottom: 6 }}>{r.name}{r.pos ? ` · ${r.pos}` : ""}{r.starter ? " · starter" : r.sub ? " · came on" : ""}</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
          {order.map(i => <span key={i} style={{ padding: "3px 7px", border: `1px solid ${T.line}`, fontSize: 11, color: T.dim, whiteSpace: "nowrap" }}>{g.labels[i]} <b style={{ color: T.ink }}>{r.stats[i]}</b></span>)}
        </div>
      </div>}
    </div>)}
    {g.totals && g.totals.some(v => v) && <div style={{ display: "grid", gridTemplateColumns: cols, columnGap: gap, padding: "6px 0", fontSize: 12, color: T.dim }}>
      <span>Team</span>{shown.map(i => <span key={i} style={{ textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{g.totals[i]}</span>)}
    </div>}
  </div>;
}

export default function App() {
  useEffect(()=>{try{document.title="Bobby's Boardroom";}catch(_){/* no document */}},[]);
  // anyone with their Kalshi key on this device: their open Kalshi positions are synced as tickets when the site opens
  // ...and every minute on any page, and the moment the tab comes back to the front
  useEffect(()=>{ if(typeof location==="undefined"||!/^https?:$/.test(location.protocol)&&!window.__api) return;
    let key=null, timer=null, alive=true;
    const run=()=>{ if(key&&!document.hidden) syncKalshi(key).catch(()=>{}); };
    api("GET","me").then(j=>j.username?savedKey(j.username):null).then(k=>{ if(!alive||!k) return; key=k; run(); timer=setInterval(run,60000); }).catch(()=>{});
    const vis=()=>{ if(!document.hidden) run(); };
    document.addEventListener("visibilitychange",vis); window.addEventListener("focus",vis);
    return ()=>{ alive=false; clearInterval(timer); document.removeEventListener("visibilitychange",vis); window.removeEventListener("focus",vis); }; },[]);
  const [phase,setPhase]=useState("setup");
  const [sport,setSport]=useState("MLB");
  const [awayInput,setAwayInput]=useState("");
  const [homeInput,setHomeInput]=useState("");
  const [isNeutral,setIsNeutral]=useState(false);
  const [matchData,setMatchData]=useState(null);
  const [simResult,setSimResult]=useState(null);
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState(null);
  const [slateRec,setSlateRec]=useState(null);
  const [slateErr,setSlateErr]=useState(null);
  const [slateStatus,setSlateStatus]=useState("");
  const [refreshing,setRefreshing]=useState(false);
  const [backTo,setBackTo]=useState(null);
  const [trackVer,setTrackVer]=useState(0);
  const [indiv,setIndiv]=useState(null);
  const [indivMatch,setIndivMatch]=useState(null);
  const [finalRow,setFinalRow]=useState(null);
  const [toolsTab,setToolsTab]=useState("book");
  // Lineups: while a game hasn't started and a side's lineup isn't posted yet, check the game every 90 seconds;
  // the moment it's posted, the matchup is re-pulled with it and re-simulated.
  const [lineupNote,setLineupNote]=useState(null);
  useEffect(()=>{
    const ref=matchData?.gameRef;
    if(phase!=="ready"||!ref?.id||ref.state!=="pre"||(ref.posted.away&&ref.posted.home))return;
    let stop=false;
    const tick=async()=>{
      try{
        const L=parseLineups(await getJSON(summaryUrl(ref.sport,ref.league,ref.id)));
        const fresh=[["away",matchData.away],["home",matchData.home]].some(([k,t])=>!ref.posted[k]&&L[t.espnId]?.official);
        if(!fresh||stop)return;
        const data=await fetchMatchup(ref.sport,ref.q.away,ref.q.home,ref.q.neutral);
        if(stop)return;
        const sim=runSimulations(data.home,data.away,ref.sport,data,10000,{neutral:ref.q.neutral});
        setMatchData(data);setSimResult(sim);
        setLineupNote(`Lineups posted at ${new Date().toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit"})}: the simulation was re-run with them.`);
      }catch(_){/* try again next tick */}
    };
    const iv=setInterval(tick,90000);
    return()=>{stop=true;clearInterval(iv);};
  },[phase,matchData]);
  useEffect(()=>{if(phase!=="ready")setLineupNote(null);},[phase]);
  // Results are tracked and graded in the background by the data job; the page only reads what it learned.
  // Browser back button: the home screen is the one history entry under the app; every other screen sits on a single
  // entry above it, so Back from anywhere (however deep) lands on the home screen instead of leaving the site.
  useEffect(()=>{
    try{ if(!history.state||!history.state.bb) history.replaceState({bb:"home"},""); }catch(_){/* no history */}
    const onPop=e=>{ if(!e.state||e.state.bb==="home"){ setPhase("setup"); setSlateErr(null); setError(null); setBackTo(null); } };
    window.addEventListener("popstate",onPop);
    return ()=>window.removeEventListener("popstate",onPop);
  },[]);
  useEffect(()=>{
    try{
      const inner=history.state&&history.state.bb==="inner";
      if(phase!=="setup"&&!inner) history.pushState({bb:"inner"},"");
      else if(phase==="setup"&&inner) history.back();          // went home with an in-app button: drop the extra entry
    }catch(_){/* no history */}
  },[phase]);
  useEffect(()=>{try{localStorage.removeItem(TRACK_LS);}catch(_){/* none */}loadLearned().then(()=>setTrackVer(v=>v+1)).catch(()=>{});},[]);

  // One ranking per scan: SLATE, BEST OF SLATE and the way back from a full sim all read the same result.
  const ranked=useMemo(()=>{
    if(!slateRec)return null;
    try{return rankSlate(slateRec.data.games,slateRec.data.sport);}catch(e){return{error:e.message||"Could not rank the slate."};}
  },[slateRec,trackVer]);
  const slateInfo=useMemo(()=>{const h=peekSlate(sport);return h?{age:Math.max(0,Math.round((Date.now()-h.t)/60000))}:null;},[sport,phase,slateRec]);

  async function openIndiv(best,force=false){
    setSlateErr(null);setError(null);
    if(!force&&indiv&&indiv.sport===sport&&Date.now()-indiv.t<SLATE_TTL_MS){setPhase(best?"indivBest":"indiv");return;}
    const onScreen=phase==="indiv"||phase==="indivBest";
    if(onScreen)setRefreshing(true);else setPhase("slateLoading");
    try{const r=await fetchIndiv(sport);setIndiv(r);setPhase(best?"indivBest":"indiv");}
    catch(e){setSlateErr(e.message||"Couldn't load today's board. Try again.");setPhase(onScreen?phase:"setup");}
    finally{setRefreshing(false);}
  }
  async function openSlate(view,force=false){
    if(isIndiv(sport))return openIndiv(view==="best",force);
    const onScreen=phase==="slate"||phase==="best";
    setSlateErr(null);setError(null);setSlateStatus("");
    if(!force){const hit=peekSlate(sport);if(hit){setSlateRec(hit);setPhase(view);return;}}
    if(force&&onScreen)setRefreshing(true);else setPhase("slateLoading");
    try{
      const rec=await getSlate(onScreen&&slateRec?slateRec.data.sport:sport,{force,onRetry:r=>setSlateStatus(`API busy or rate limited. Retrying in ${Math.round(r.waitMs/1000)}s (${r.attempt}/${r.retries})`)});
      setSlateRec(rec);setPhase(view);
    }catch(e){
      setSlateErr(e.message||"Slate scan failed. Try again.");
      setPhase(onScreen?view:"setup");
    }finally{setRefreshing(false);}
  }

  async function handleFetch(ov) {
    const o=ov&&typeof ov.away==="string"?ov:null;   // a click passes the event object; slate rows pass overrides
    const sp=o&&o.sport?o.sport:sport,a=(o?o.away:awayInput).trim(),h=(o?o.home:homeInput).trim(),n=o?!!o.neutral:isNeutral;
    if(o){setAwayInput(a);setHomeInput(h);setIsNeutral(n);if(sp!==sport)setSport(sp);}else setBackTo(null);
    if(isIndiv(sp)){
      setLoading(true);setError(null);setPhase("slateLoading");
      try{setIndivMatch(await indivMatchup(sp,a,h,o&&o.row||null));setPhase("indivMatch");}
      catch(e){setError(e.message||"Couldn't find those two.");setPhase("setup");}
      finally{setLoading(false);}
      return;
    }
    setLoading(true); setError(null); setPhase("loading");
    try {
      const data = await fetchMatchup(sp, a, h, n);
      setMatchData(data);
      // Auto-simulate immediately — no button needed
      const sim = runSimulations(data.home, data.away, sp, data, 10000, { neutral: n });
      setSimResult(sim);
      setPhase("ready");
    } catch(e) {
      setError(e.message||"Failed to load data. Check team names and try again.");
      setPhase(o&&o.from?o.from:"setup");
    } finally {
      setLoading(false);
    }
  }
  const runFull=(row,from)=>{setBackTo(from);handleFetch({away:row.md.away.name,home:row.md.home.name,neutral:row.neutral,sport:slateRec.data.sport,from});};

  if ((phase==="indiv"||phase==="indivBest")&&indiv) return <IndivSlateScreen res={indiv} best={phase==="indivBest"} refreshing={refreshing} onSim={indiv.sport==="Tennis"?m=>{setIndivMatch({sport:"Tennis",match:m,fit:indiv.fit,from:phase});setPhase("indivMatch");}:null} onBack={()=>setPhase("setup")} onRefresh={()=>openIndiv(phase==="indivBest",true)} onToggle={()=>setPhase(phase==="indiv"?"indivBest":"indiv")}/>;
  if (phase==="indivMatch"&&indivMatch) return indivMatch.sport==="Tennis"?<TennisSimScreen res={indivMatch} onBack={()=>setPhase(indivMatch.from||"setup")} onReset={()=>setPhase("setup")}/>:<IndivMatchScreen res={indivMatch} onBack={()=>setPhase("setup")}/>;
  if (phase==="bets") return <BetSlipsScreen onBack={()=>setPhase("setup")} onTools={()=>{setToolsTab("kalshi");setPhase("tools");}}/>;
  if (phase==="tools") return <ToolsScreen start={toolsTab} onBack={()=>setPhase("setup")}/>;
  if (phase==="final"&&finalRow) return <FinalScreen sport={finalRow.sport} row={finalRow.row} onBack={()=>setPhase("setup")}/>;
  if (phase==="box"&&finalRow) { const r=finalRow.row; return <FinalScreen live sport={finalRow.sport} row={r} onBack={()=>setPhase("setup")} onSim={()=>handleFetch({away:r.away.full||r.away.name,home:r.home.full||r.home.name,neutral:false,sport:finalRow.sport,row:r})}/>; }
  if (phase==="loading") return <LoadingScreen awayName={awayInput} homeName={homeInput} sport={sport}/>;
  if (phase==="slateLoading") return <SlateLoading sport={sport} status={slateStatus}/>;
  if ((phase==="slate"||phase==="best")&&slateRec&&ranked&&!ranked.error) {
    const meta={t:slateRec.t,slateDate:slateRec.data.slateDate,sources:slateRec.data.sources};
    const common={ranked,sport:slateRec.data.sport,meta,refreshing,err:slateErr||error,
      onRefresh:()=>openSlate(phase,true),onRunFull:r=>runFull(r,phase),onBack:()=>{setPhase("setup");setSlateErr(null);setError(null);}};
    return phase==="slate"?<SlateScreen {...common} onBest={()=>setPhase("best")}/>:<BestPickScreen {...common} onSlate={()=>setPhase("slate")}/>;
  }
  if (phase==="ready"&&matchData&&simResult) return <SimScreen lineupNote={lineupNote} matchData={matchData} simResult={simResult} sport={sport} isNeutral={isNeutral} onBack={backTo&&ranked&&!ranked.error?()=>setPhase(backTo):null} onReset={()=>{setPhase("setup");setMatchData(null);setSimResult(null);setBackTo(null);}}/>;
  return <SetupScreen sport={sport} setSport={setSport} awayInput={awayInput} setAwayInput={setAwayInput} homeInput={homeInput} setHomeInput={setHomeInput} isNeutral={isNeutral} setIsNeutral={setIsNeutral} onFetch={handleFetch} loading={loading} error={error}
    onSlate={()=>openSlate("slate")} onBest={()=>openSlate("best")} onBets={()=>setPhase("bets")} onTools={()=>{setToolsTab("book");setPhase("tools");}} onFinal={r=>{setFinalRow({sport,row:r});setPhase("final");}} onBox={r=>{setFinalRow({sport,row:r});setPhase("box");}} slateInfo={slateInfo} slateBusy={false} slateErr={slateErr||(ranked&&ranked.error)||null}
    onPick={r=>handleFetch({away:r.away.full||r.away.name,home:r.home.full||r.home.name,neutral:false,sport,row:r})}/>;
}
